import { createContext, useContext } from "react"
import type { DataSchema, GlobalQueryFolder, GlobalSavedQuery } from "@/lib/mapsvg-api"

export type DatabaseSection = "collections" | "queries"

export type DatabaseNavigationContextValue = {
  section: DatabaseSection
  setSection: (section: DatabaseSection) => void

  schemas: DataSchema[]
  schemasLoaded: boolean
  loading: boolean
  error: string | null
  refreshSchemas: (shouldCommit?: () => boolean) => Promise<DataSchema[]>

  queriesEnabled: boolean
  folders: GlobalQueryFolder[]
  queries: GlobalSavedQuery[]
  loadingQueries: boolean
  queriesLoaded: boolean
  queryError: string | null
  refreshQueries: (
    shouldCommit?: () => boolean,
    onCommit?: (queries: GlobalSavedQuery[]) => void,
  ) => Promise<GlobalSavedQuery[]>

  selectedQueryId: string | null
  setSelectedQueryId: (id: string | null) => void
  creatingQuery: boolean
  newQueryFolderId: number | null
  startQuery: (folderId?: number | null) => void
  cancelQueryCreation: () => void
}

export const DatabaseNavigationContext = createContext<DatabaseNavigationContextValue | null>(null)

export function useDatabaseNavigation(): DatabaseNavigationContextValue {
  const value = useContext(DatabaseNavigationContext)
  if (!value) {
    throw new Error("useDatabaseNavigation must be used inside DatabaseNavigationProvider")
  }
  return value
}
