import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react"
import {
  DatabaseNavigationContext,
  type DatabaseSection,
} from "@/components/database/database-navigation-context"
import { getAdminParams } from "@/lib/admin-params"
import {
  fetchGlobalQueries,
  fetchQueryFolders,
  fetchSchemas,
  schemaDisplayTitle,
  type DataSchema,
  type GlobalQueryFolder,
  type GlobalSavedQuery,
} from "@/lib/mapsvg-api"

function sortSchemas(schemas: DataSchema[]): DataSchema[] {
  return [...schemas].sort((a, b) => schemaDisplayTitle(a).localeCompare(schemaDisplayTitle(b)))
}

export function DatabaseNavigationProvider({ children, initialQueryId = null }: { children: ReactNode; initialQueryId?: string | null }) {
  const [section, setSection] = useState<DatabaseSection>(initialQueryId ? "queries" : "collections")
  const [schemas, setSchemas] = useState<DataSchema[]>([])
  const [schemasLoaded, setSchemasLoaded] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const queriesEnabled = getAdminParams().globalQueriesEnabled
  const [folders, setFolders] = useState<GlobalQueryFolder[]>([])
  const [queries, setQueries] = useState<GlobalSavedQuery[]>([])
  const [loadingQueries, setLoadingQueries] = useState(false)
  const [queriesLoaded, setQueriesLoaded] = useState(false)
  const [queryError, setQueryError] = useState<string | null>(null)
  const [selectedQueryId, setSelectedQueryIdState] = useState<string | null>(initialQueryId)
  const [creatingQuery, setCreatingQuery] = useState(false)
  const [newQueryFolderId, setNewQueryFolderId] = useState<number | null>(null)
  useLayoutEffect(() => {
    setSelectedQueryIdState(initialQueryId)
    setSection(initialQueryId ? "queries" : "collections")
    setCreatingQuery(false)
    setNewQueryFolderId(null)
  }, [initialQueryId])
  const mounted = useRef(false)
  const schemaRead = useRef(0)
  const queryRead = useRef(0)
  useLayoutEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      schemaRead.current++
      queryRead.current++
    }
  }, [])

  const refreshSchemas = useCallback(async (shouldCommit?: () => boolean) => {
    const run = ++schemaRead.current
    const current = () => mounted.current && schemaRead.current === run
    setLoading(true)
    setError(null)
    try {
      const next = sortSchemas(await fetchSchemas())
      if (current() && (!shouldCommit || shouldCommit())) {
        setSchemas(next)
        setSchemasLoaded(true)
      }
      return next
    } catch (failure) {
      if (current() && (!shouldCommit || shouldCommit())) {
        setError(failure instanceof Error ? failure.message : String(failure))
      }
      throw failure
    } finally {
      if (current()) setLoading(false)
    }
  }, [])

  const refreshQueries = useCallback(
    async (shouldCommit?: () => boolean, onCommit?: (queries: GlobalSavedQuery[]) => void) => {
      if (!queriesEnabled) return []
      const run = ++queryRead.current
      const current = () => mounted.current && queryRead.current === run
      setLoadingQueries(true)
      setQueryError(null)
      try {
        const [nextFolders, nextQueries] = await Promise.all([
          fetchQueryFolders(),
          fetchGlobalQueries(),
        ])
        if (!current() || (shouldCommit && !shouldCommit())) return nextQueries
        setFolders(nextFolders)
        setQueries(nextQueries)
        setSelectedQueryIdState((selected) =>
          selected && (selected === initialQueryId || nextQueries.some((query) => query.id === selected))
            ? selected
            : (nextQueries[0]?.id ?? null),
        )
        onCommit?.(nextQueries)
        return nextQueries
      } catch (failure) {
        if (current() && (!shouldCommit || shouldCommit())) {
          setQueryError(failure instanceof Error ? failure.message : String(failure))
        }
        throw failure
      } finally {
        if (current()) {
          setQueriesLoaded(true)
          setLoadingQueries(false)
        }
      }
    },
    [queriesEnabled, initialQueryId],
  )

  useEffect(() => {
    void refreshSchemas().catch(() => {})
  }, [refreshSchemas])

  useEffect(() => {
    if (section === "queries" && !queriesLoaded && !loadingQueries) {
      void refreshQueries().catch(() => {})
    }
  }, [section, queriesLoaded, loadingQueries, refreshQueries])

  useEffect(() => {
    const onSchemaMutation = () => {
      void refreshSchemas().catch(() => {})
    }
    const onQueryMutation = () => {
      void refreshQueries().catch(() => {})
    }
    const onMapMutation = (event: Event) => {
      const detail = (event as CustomEvent<{ action?: string }>).detail
      if (detail?.action === "created" || detail?.action === "duplicated") {
        void refreshSchemas().catch(() => {})
      }
      if (detail?.action === "created") {
        void refreshQueries().catch(() => {})
      }
    }

    window.addEventListener("mapsvg:schema-mutation", onSchemaMutation)
    window.addEventListener("mapsvg:query-mutation", onQueryMutation)
    window.addEventListener("mapsvg:map-mutation", onMapMutation)
    return () => {
      window.removeEventListener("mapsvg:schema-mutation", onSchemaMutation)
      window.removeEventListener("mapsvg:query-mutation", onQueryMutation)
      window.removeEventListener("mapsvg:map-mutation", onMapMutation)
    }
  }, [refreshQueries, refreshSchemas])

  const setSelectedQueryId = useCallback((id: string | null) => {
    setCreatingQuery(false)
    setNewQueryFolderId(null)
    setSelectedQueryIdState(id)
  }, [])

  const startQuery = useCallback((folderId: number | null = null) => {
    setSection("queries")
    setCreatingQuery(true)
    setNewQueryFolderId(folderId)
  }, [])

  const cancelQueryCreation = useCallback(() => {
    setCreatingQuery(false)
    setNewQueryFolderId(null)
  }, [])

  const value = useMemo(
    () => ({
      section,
      setSection,
      schemas,
      schemasLoaded,
      loading,
      error,
      refreshSchemas,
      queriesEnabled,
      folders,
      queries,
      loadingQueries,
      queriesLoaded,
      queryError,
      refreshQueries,
      selectedQueryId,
      setSelectedQueryId,
      creatingQuery,
      newQueryFolderId,
      startQuery,
      cancelQueryCreation,
    }),
    [
      section,
      schemas,
      schemasLoaded,
      loading,
      error,
      refreshSchemas,
      queriesEnabled,
      folders,
      queries,
      loadingQueries,
      queriesLoaded,
      queryError,
      refreshQueries,
      selectedQueryId,
      setSelectedQueryId,
      creatingQuery,
      newQueryFolderId,
      startQuery,
      cancelQueryCreation,
    ],
  )

  return (
    <DatabaseNavigationContext.Provider value={value}>
      {children}
    </DatabaseNavigationContext.Provider>
  )
}
