import {
  ChevronRight,
  DatabaseArrowDown,
  FolderIcon,
  PencilIcon,
  PlusIcon,
  Search,
  SquareArrowOutUpRight,
  Table2,
  Trash2Icon,
} from "lucide-react"
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useDatabaseNavigation } from "@/components/database/database-navigation-context"
import { CreateCollectionDialog } from "@/components/database/CreateCollectionDialog"
import { getAdminParams } from "@/lib/admin-params"
import {
  createQueryFolder,
  deleteQueryFolder,
  renameQueryFolder,
  schemaDisplayTitle,
  type DataSchema,
  type GlobalQueryFolder,
  type GlobalSavedQuery,
} from "@/lib/mapsvg-api"
import { cn } from "@/lib/utils"

type FolderAction = { type: "create" } | { type: "rename" | "delete"; folder: GlobalQueryFolder }

type Props = {
  selectedSchemaId: string | null
  onSelectSchema: (schema: DataSchema) => void
  onSelectQuery?: (query: GlobalSavedQuery) => void
  onOpenSchemaTab?: (schema: DataSchema) => void
  onOpenQueryTab?: (query: GlobalSavedQuery) => void
  onSectionChange?: (section: "collections" | "queries") => void
  onCatalogReady?: (schemas: DataSchema[], queries: GlobalSavedQuery[]) => void
  onQueryCatalogReady?: (queries: GlobalSavedQuery[]) => void
}

export function DatabaseSecondarySidebar({
  selectedSchemaId,
  onSelectSchema,
  onSelectQuery,
  onOpenSchemaTab,
  onOpenQueryTab,
  onSectionChange,
  onCatalogReady,
  onQueryCatalogReady,
}: Props) {
  const {
    section,
    setSection,
    schemas,
    schemasLoaded,
    loading,
    error,
    refreshSchemas,
    folders,
    queries,
    loadingQueries,
    queriesLoaded,
    queryError,
    refreshQueries,
    selectedQueryId,
    setSelectedQueryId,
    startQuery,
    queriesEnabled,
  } = useDatabaseNavigation()
  const [collectionSearch, setCollectionSearch] = useState("")
  const [creatingCollection, setCreatingCollection] = useState(false)
  const [querySearch, setQuerySearch] = useState("")
  const [expandedFolders, setExpandedFolders] = useState<Set<number>>(new Set())
  const [folderAction, setFolderAction] = useState<FolderAction | null>(null)
  const [folderTitle, setFolderTitle] = useState("")
  const [folderError, setFolderError] = useState<string | null>(null)
  const [folderBusy, setFolderBusy] = useState(false)
  const [folderCommitted, setFolderCommitted] = useState(false)
  const folderLife = useRef<object | null>(null)
  const folderPending = useRef<object | null>(null)
  const sectionButtons = useRef<Array<HTMLButtonElement | null>>([])
  useLayoutEffect(() => {
    const owner = {}
    folderLife.current = owner
    return () => {
      if (folderLife.current === owner) folderLife.current = null
    }
  }, [])

  useEffect(() => {
    if (schemasLoaded && !loading && !error) onCatalogReady?.(schemas, queries)
  }, [schemasLoaded, loading, error, onCatalogReady, queries, schemas])

  useEffect(() => {
    if (queriesLoaded && !loadingQueries && !queryError) onQueryCatalogReady?.(queries)
  }, [queriesLoaded, loadingQueries, queryError, queries, onQueryCatalogReady])

  const selectedFolderId = queries.find((query) => query.id === selectedQueryId)?.folderId
  useEffect(() => {
    if (selectedFolderId != null) {
      setExpandedFolders((current) => new Set(current).add(selectedFolderId))
    }
  }, [selectedFolderId, selectedQueryId])

  const searchText = section === "collections" ? collectionSearch : querySearch
  const search = searchText.trim().toLowerCase()

  const filteredSchemas = useMemo(() => {
    if (!search) return schemas
    return schemas.filter(
      (schema) =>
        schemaDisplayTitle(schema).toLowerCase().includes(search) ||
        schema.name.toLowerCase().includes(search),
    )
  }, [schemas, search])

  const filteredQueries = useMemo(
    () => queries.filter((query) => !search || query.name.toLowerCase().includes(search)),
    [queries, search],
  )

  const folderGroups = folders.map((folder) => ({
    folder,
    items: (search && folder.title.toLowerCase().includes(search)
      ? queries
      : filteredQueries
    ).filter((query) => query.folderId === folder.id),
  }))
  const visibleFolderGroups = folderGroups.filter(
    ({ folder, items }) =>
      !search || folder.title.toLowerCase().includes(search) || items.length > 0,
  )
  const unfiled = (search && "unfiled".includes(search) ? queries : filteredQueries).filter(
    (query) => query.folderId === null || !folders.some((folder) => folder.id === query.folderId),
  )

  const changeSection = (next: "collections" | "queries") => {
    setCreatingCollection(false)
    setSection(next)
    onSectionChange?.(next)
  }

  const selectQuery = (query: GlobalSavedQuery) => {
    setSelectedQueryId(query.id)
    setCreatingCollection(false)
    setSection("queries")
    if (onSelectQuery) onSelectQuery(query)
    else onSectionChange?.("queries")
  }

  const beginQuery = (folderId: number | null) => {
    startQuery(folderId)
    onSectionChange?.("queries")
  }

  const toggleFolder = (id: number) =>
    setExpandedFolders((current) => {
      const next = new Set(current)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })

  const openFolderAction = (action: FolderAction) => {
    if (folderPending.current) return
    setFolderAction(action)
    setFolderTitle(action.type === "create" ? "" : action.folder.title)
    setFolderError(null)
    setFolderCommitted(false)
  }

  const submitFolderAction = async () => {
    const owner = folderLife.current
    if (!owner || !folderAction || folderPending.current) return
    const action = folderAction
    const title = folderTitle.trim()
    const token = {}
    const current = () => folderLife.current === owner && folderPending.current === token
    folderPending.current = token
    try {
      if (!folderCommitted && action.type !== "delete" && !title) {
        throw new Error("Enter a folder title.")
      }
      setFolderBusy(true)
      setFolderError(null)
      if (!folderCommitted) {
        if (action.type === "create") await createQueryFolder(title)
        else if (action.type === "rename") await renameQueryFolder(action.folder.id, title)
        else await deleteQueryFolder(action.folder.id)
        if (!current()) return
        setFolderCommitted(true)
      }
      await refreshQueries(current)
      if (!current()) return
      setFolderAction(null)
      setFolderCommitted(false)
      setFolderError(null)
    } catch (failure) {
      if (current()) setFolderError(failure instanceof Error ? failure.message : String(failure))
    } finally {
      if (current()) {
        folderPending.current = null
        setFolderBusy(false)
      }
    }
  }

  const queryRow = (query: GlobalSavedQuery) => (
    <div key={query.id} className={cn("group/database-resource relative rounded-md hover:bg-accent", selectedQueryId === query.id && "bg-accent font-medium")}>
    <button
      type="button"
      onClick={() => selectQuery(query)}
      className={cn(
        "flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 pr-8 text-left text-sm",
        selectedQueryId === query.id && "bg-accent font-medium",
      )}
      title={query.name}
      data-query-id={query.id}
      aria-current={selectedQueryId === query.id ? "true" : undefined}
    >
      <DatabaseArrowDown className="size-3.5 shrink-0 text-muted-foreground" />
      <span className="truncate font-mono text-xs">{query.name}</span>
    </button>
    {onOpenQueryTab ? (
      <Tooltip>
        <TooltipTrigger asChild>
          <Button type="button" variant="ghost" size="icon-xs" className="absolute right-1 top-1/2 -translate-y-1/2 text-muted-foreground opacity-0 hover:text-foreground group-hover/database-resource:opacity-100 group-focus-within/database-resource:opacity-100"
            aria-label={`Open query ${query.name} in new tab`} onClick={event => { event.stopPropagation(); onOpenQueryTab(query) }}>
            <SquareArrowOutUpRight className="size-3.5" />
          </Button>
        </TooltipTrigger>
        <TooltipContent>Open in new MapSVG tab</TooltipContent>
      </Tooltip>
    ) : null}
    </div>
  )

  return (
    <>
      <aside className="flex h-full w-56 shrink-0 flex-col border-r border-border bg-background">
        <header
          className="flex h-10 shrink-0 gap-1 border-b border-border p-1.5"
          role="tablist"
          aria-label="Database sections"
        >
          {(["collections", "queries"] as const).map((tab, index) => (
            <button
              key={tab}
              type="button"
              role="tab"
              ref={(button) => {
                sectionButtons.current[index] = button
              }}
              tabIndex={section === tab ? 0 : -1}
              onKeyDown={(event) => {
                const nextIndex =
                  event.key === "Home"
                    ? 0
                    : event.key === "End"
                      ? 1
                      : event.key === "ArrowRight" || event.key === "ArrowLeft"
                        ? 1 - index
                        : null
                if (nextIndex === null) return
                event.preventDefault()
                changeSection(nextIndex === 0 ? "collections" : "queries")
                sectionButtons.current[nextIndex]?.focus()
              }}
              aria-selected={section === tab}
              onClick={() => changeSection(tab)}
              className={cn(
                "flex-1 rounded-md px-2 py-1.5 text-xs font-medium hover:bg-accent",
                section === tab ? "bg-accent text-foreground" : "text-muted-foreground",
              )}
            >
              {tab === "collections" ? "Collections" : "Queries"}
            </button>
          ))}
        </header>

        <div
          data-slot="database-search-toolbar"
          className="flex h-10 shrink-0 items-center border-b border-border px-2"
        >
          <div className="relative w-full min-w-0">
            <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={searchText}
              onChange={(event) =>
                section === "collections"
                  ? setCollectionSearch(event.target.value)
                  : setQuerySearch(event.target.value)
              }
              aria-label={section === "collections" ? "Search collections" : "Search queries"}
              placeholder={section === "collections" ? undefined : "Search queries…"}
              className="h-7! pl-8! text-xs!"
            />
          </div>
        </div>

        {section === "collections" && getAdminParams().user?.isAdmin ? (
          <div className="border-b border-border p-2">
            <Button
              type="button"
              variant="outline"
              size="xs"
              className="w-full"
              onClick={() => setCreatingCollection(true)}
            >
              <PlusIcon /> New
            </Button>
          </div>
        ) : null}

        {section === "queries" && queriesEnabled ? (
          <div className="flex gap-1 border-b border-border p-2">
            <Button
              type="button"
              variant="outline"
              size="xs"
              className="flex-1"
              onClick={() => openFolderAction({ type: "create" })}
            >
              <PlusIcon />
              Folder
            </Button>
            <Button
              type="button"
              variant="outline"
              size="xs"
              className="flex-1"
              onClick={() => beginQuery(null)}
            >
              <PlusIcon />
              Query
            </Button>
          </div>
        ) : null}

        <nav
          className={cn(
            "min-h-0 flex-1 overflow-y-auto",
            section === "collections" ? "p-1.5" : "p-2",
          )}
          aria-label={section === "collections" ? "Database tables" : "Database queries"}
        >
          {section === "collections" ? (
            loading ? (
              <p className="px-2 py-2 text-xs text-muted-foreground">Loading…</p>
            ) : error ? (
              <div className="px-2 py-2 text-xs">
                <p role="alert" className="text-destructive">
                  {error}
                </p>
                <Button
                  size="xs"
                  variant="outline"
                  onClick={() => void refreshSchemas().catch(() => {})}
                >
                  Retry collections
                </Button>
              </div>
            ) : filteredSchemas.length === 0 ? (
              <p className="px-2 py-2 text-xs text-muted-foreground">No tables.</p>
            ) : (
              <div className="flex flex-col gap-0.5">
                {filteredSchemas.map((schema) => {
                  const id = String(schema.id)
                  const title = schemaDisplayTitle(schema)
                  return (
                    <div key={id} className={cn("group/database-resource relative rounded-md hover:bg-accent", selectedSchemaId === id && "bg-accent font-medium")}>
                    <button
                      type="button"
                      onClick={() => {
                        setSection("collections")
                        onSelectSchema(schema)
                      }}
                      className={cn(
                        "flex w-full min-w-0 items-center gap-1.5 rounded-md px-1.5 py-1 pr-8 text-left text-xs",
                        selectedSchemaId === id && "bg-accent font-medium",
                      )}
                      title={schema.name}
                      data-schema-id={id}
                      aria-current={selectedSchemaId === id ? "true" : undefined}
                    >
                      <Table2 className="size-3.5 shrink-0 text-muted-foreground" />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate">{title}</span>
                        {title !== schema.name ? (
                          <span className="block truncate font-mono text-[10px] text-muted-foreground">
                            {schema.name}
                          </span>
                        ) : null}
                      </span>
                    </button>
                    {onOpenSchemaTab ? (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button type="button" variant="ghost" size="icon-xs" className="absolute right-1 top-1/2 -translate-y-1/2 text-muted-foreground opacity-0 hover:text-foreground group-hover/database-resource:opacity-100 group-focus-within/database-resource:opacity-100"
                            aria-label={`Open collection ${title} in new tab`} onClick={event => { event.stopPropagation(); onOpenSchemaTab(schema) }}>
                            <SquareArrowOutUpRight className="size-3.5" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Open in new MapSVG tab</TooltipContent>
                      </Tooltip>
                    ) : null}
                    </div>
                  )
                })}
              </div>
            )
          ) : !queriesEnabled ? (
            <p className="px-2 py-2 text-xs text-muted-foreground">
              Queries require Global Queries to be enabled.
            </p>
          ) : loadingQueries ? (
            <p className="px-2 py-2 text-xs text-muted-foreground">Loading…</p>
          ) : queryError ? (
            <div className="px-2 py-2 text-xs">
              <p role="alert" className="text-destructive">
                {queryError}
              </p>
              <Button
                size="xs"
                variant="outline"
                onClick={() => void refreshQueries().catch(() => {})}
              >
                Retry queries
              </Button>
            </div>
          ) : (
            <div className="flex flex-col gap-1">
              {visibleFolderGroups.map(({ folder, items }) => {
                const expanded = search ? true : expandedFolders.has(folder.id)
                return (
                  <div key={folder.id} data-query-folder-id={folder.id}>
                    <div className="group flex items-center rounded-md hover:bg-accent">
                      <button
                        type="button"
                        className="flex min-w-0 flex-1 items-center gap-1.5 px-1 py-1.5 text-left text-sm"
                        aria-expanded={expanded}
                        onClick={() => toggleFolder(folder.id)}
                      >
                        <ChevronRight
                          className={cn(
                            "size-3.5 shrink-0 text-muted-foreground",
                            expanded && "rotate-90",
                          )}
                        />
                        <FolderIcon className="size-3.5 shrink-0 text-muted-foreground" />
                        <span className="truncate" title={folder.title}>
                          {folder.title}
                        </span>
                      </button>
                      <button
                        type="button"
                        className="hidden p-1 text-muted-foreground hover:text-foreground group-hover:block group-focus-within:block focus:block"
                        aria-label={`New query in ${folder.title}`}
                        onClick={() => beginQuery(folder.id)}
                      >
                        <PlusIcon className="size-3.5" />
                      </button>
                      <button
                        type="button"
                        className="hidden p-1 text-muted-foreground hover:text-foreground group-hover:block group-focus-within:block focus:block"
                        aria-label={`Rename ${folder.title}`}
                        onClick={() => openFolderAction({ type: "rename", folder })}
                      >
                        <PencilIcon className="size-3.5" />
                      </button>
                      <button
                        type="button"
                        className="hidden p-1 text-muted-foreground hover:text-destructive group-hover:block group-focus-within:block focus:block"
                        aria-label={`Delete ${folder.title}`}
                        onClick={() => openFolderAction({ type: "delete", folder })}
                      >
                        <Trash2Icon className="size-3.5" />
                      </button>
                    </div>
                    {expanded ? (
                      <div className="ml-3 border-l pl-2">
                        {items.length ? (
                          items.map(queryRow)
                        ) : (
                          <p className="px-2 py-1 text-xs text-muted-foreground">Empty folder</p>
                        )}
                      </div>
                    ) : null}
                  </div>
                )
              })}

              {unfiled.length > 0 ? (
                <div>
                  <div className="px-2 py-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                    Unfiled
                  </div>
                  {unfiled.map(queryRow)}
                </div>
              ) : null}

              {search && visibleFolderGroups.length === 0 && unfiled.length === 0 ? (
                <p className="px-2 py-2 text-xs text-muted-foreground">
                  No matching queries or folders.
                </p>
              ) : null}

              {!search && queries.length === 0 && folders.length === 0 ? (
                <p className="px-2 py-2 text-xs text-muted-foreground">No queries yet.</p>
              ) : null}
            </div>
          )}
        </nav>
      </aside>

      {creatingCollection && section === "collections" ? (
        <CreateCollectionDialog
          schemas={schemas}
          onClose={() => setCreatingCollection(false)}
          onCreated={async (schema, current) => {
            const catalog = await refreshSchemas(current)
            if (!current()) return
            const persisted = catalog.find((item) => String(item.id) === String(schema.id))
            if (!persisted)
              throw new Error(
                "The created Collection is not in the catalog. Reload the catalog to continue.",
              )
            setCollectionSearch("")
            onSelectSchema(persisted)
          }}
        />
      ) : null}

      <Dialog
        open={folderAction !== null}
        onOpenChange={(open) => {
          if (!open && !folderPending.current) setFolderAction(null)
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {folderAction?.type === "create"
                ? "New folder"
                : folderAction?.type === "rename"
                  ? "Rename folder"
                  : "Delete folder"}
            </DialogTitle>
            {folderAction?.type === "delete" ? (
              <DialogDescription>
                Queries in “{folderAction.folder.title}” will move to Unfiled.
              </DialogDescription>
            ) : null}
          </DialogHeader>
          {folderAction && folderAction.type !== "delete" ? (
            <div className="grid gap-2">
              <Label htmlFor="global-query-folder-title">Folder title</Label>
              <Input
                id="global-query-folder-title"
                autoFocus
                disabled={folderBusy || folderCommitted}
                value={folderTitle}
                onChange={(event) => {
                  setFolderTitle(event.target.value)
                  setFolderError(null)
                }}
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    event.preventDefault()
                    void submitFolderAction()
                  }
                }}
              />
            </div>
          ) : null}
          {folderError ? (
            <p role="alert" className="text-sm text-destructive">
              {folderError}
            </p>
          ) : null}
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              disabled={folderBusy}
              onClick={() => setFolderAction(null)}
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant={folderAction?.type === "delete" ? "destructive" : "default"}
              disabled={folderBusy}
              onClick={() => void submitFolderAction()}
            >
              {folderCommitted
                ? "Reload catalog"
                : folderAction?.type === "create"
                  ? "Create"
                  : folderAction?.type === "rename"
                    ? "Save"
                    : "Delete"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}
