import { schemaUsesPostData } from "../../../../mapsvg/Core/productFeatures"
import { hasProductFeature } from "@/lib/product-features"
import { ProductFeaturePlaceholder } from "@/components/PremiumFeaturePlaceholder"
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { CopyPlusIcon, PlusIcon, SaveIcon, Trash2Icon } from "lucide-react"
import { DataListTable } from "@/components/data/DataListTable"
import {
  COMPLEX_FIELD_CONTEXT_KEY,
  createWordPressMediaPicker,
  createWordPressPostAdapter,
} from "@/components/form-builder/complex-fields"
import {
  LOCATION_FIELD_CONTEXT_KEY,
  createStandaloneLocationAdapter,
} from "@/components/form-builder/location-field"
import {
  SchemaBuilder,
  type SchemaBuilderSaveState,
} from "@/components/form-builder/schema-builder"
import { SchemaForm } from "@/components/form-builder/schema-form"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useDatabaseNavigation } from "@/components/database/database-navigation-context"
import { recordSchemaKey, useCollectionEditorDefaults } from "@/lib/collection-editor-defaults"
import { DatabaseCsvImport } from "@/components/database/import/DatabaseCsvImport"
import { CollectionSettings } from "@/components/database/CollectionSettings"
import {
  createCollectionRegionAdapter,
  regionCatalogKey,
} from "@/components/form-builder/complex-fields/collectionRegionAdapter"
import { getAdminParams } from "@/lib/admin-params"
import {
  createCollectionRow,
  fetchCollectionPage,
  deleteCollectionRow,
  type CollectionPage,
  schemaDisplayTitle,
  updateCollectionRow,
  updateSchemaFields,
  type SchemaField,
  type ZodSettings,
} from "@/lib/mapsvg-api"
import { duplicateCollectionRecord } from "@/lib/duplicate-collection-record"
import { isRecordValidationError } from "@/lib/record-validation-error"
import { cn } from "@/lib/utils"
import type { FormFieldData } from "../../../../mapsvg/FormBuilder/FieldDefinitions"

type DataRow = Record<string, unknown>
const EMPTY_NEW_ROW: DataRow = {}
const COLLECTION_SCHEMA_FORM_ID = "database-table-schema-form"
type CollectionViewMode = "rows" | "fields" | "import" | "settings"

type Props = {
  schemaId: string | null
}

export function DatabaseTableWorkspace({ schemaId }: Props) {
  const importEnabled = getAdminParams().databaseImportEnabled
  const {
    schemas,
    loading: loadingSchemas,
    error: schemaError,
    refreshSchemas,
  } = useDatabaseNavigation()
  const [requestedCollectionMode, setCollectionMode] = useState<CollectionViewMode>("rows")
  const collectionMode = requestedCollectionMode
  const [rows, setRows] = useState<DataRow[]>([])
  const [selectedRow, setSelectedRow] = useState<DataRow | null>(null)
  const [newRecord, setNewRecord] = useState<{ collection: object; value: DataRow } | null>(null)
  const [loadingRows, setLoadingRows] = useState(false)
  const [pageState, setPageState] = useState<{ owner: object; result: CollectionPage } | null>(null)
  const [browse, setBrowse] = useState({ key: "", pageIndex: 0, search: "" })
  const [retry, setRetry] = useState(0)
  const [recordMutation, setRecordMutation] = useState<object | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [schemaSaveState, setSchemaSaveState] = useState<SchemaBuilderSaveState>({
    dirty: false,
    valid: true,
  })

  const catalogSchema = schemas.find((item) => String(item.id) === schemaId) ?? null
  const postsLocked = schemaUsesPostData(catalogSchema) && !hasProductFeature("data_source_posts")
  const schemaKey = recordSchemaKey(catalogSchema)
  const editorPreferences = useCollectionEditorDefaults(catalogSchema)
  // Equivalent catalog refreshes must not reset a record or Fields draft.
  const schema = useMemo(() => catalogSchema, [schemaKey])
  const collectionOwner = useMemo(() => ({}), [schemaId, schemaKey])
  const creatingRow = newRecord?.collection === collectionOwner
  const browseKey = `${schemaId}:${schemaKey}`
  const pageIndex = browse.key === browseKey ? browse.pageIndex : 0
  const search = browse.key === browseKey ? browse.search : ""
  const queryOwner = useMemo(() => ({}), [collectionOwner, pageIndex, search])
  const pageResult = pageState?.owner === queryOwner ? pageState.result : null
  const setPageResult = (result: CollectionPage | null) => setPageState(result ? { owner: queryOwner, result } : null)
  const pageOptions = { page: pageIndex + 1, perpage: 50, search }
  const owner = useMemo(
    () => ({}),
    [
      queryOwner,
      collectionMode,
      creatingRow,
      collectionMode === "rows" ? selectedRow?.id : null,
    ],
  )
  const current = useRef<{ collection: object; query: object; view: object; creating: boolean } | null>(null)
  const previousMode = useRef(collectionMode)
  useEffect(() => {
    if (previousMode.current === "import" && collectionMode === "rows") setRetry((value) => value + 1)
    previousMode.current = collectionMode
  }, [collectionMode])
  const readRun = useRef(0)
  const mutationRun = useRef(0)
  useLayoutEffect(() => {
    current.current = { collection: collectionOwner, query: queryOwner, view: owner, creating: creatingRow }
    return () => {
      current.current = null
      mutationRun.current++
    }
  }, [collectionOwner, queryOwner, owner])
  const editableFields = useMemo(() => (schema?.fields ?? []) as FormFieldData[], [schema])
  const sourcesKey = regionCatalogKey(schemas)
  const rememberRegionSource = useCallback((name: string) => editorPreferences.remember({ regionsTableName: name }), [editorPreferences.remember])
  const rememberPickerMap = useCallback((mapId: number) => editorPreferences.remember({ mapId }), [editorPreferences.remember])
  const rememberMarkerImage = useCallback((defaultMarkerImage: string) => editorPreferences.remember({ defaultMarkerImage }), [editorPreferences.remember])
  const regionAdapter = useMemo(() => createCollectionRegionAdapter(schemas, {
    tableName: editorPreferences.defaults.regionsTableName ?? "", rememberSource: rememberRegionSource, preferenceKey: String(schemaId), preferenceError: editorPreferences.error,
  }), [sourcesKey, editorPreferences.defaults.regionsTableName, rememberRegionSource, schemaId, editorPreferences.error])
  const locationAdapter = useMemo(() => createStandaloneLocationAdapter({ markerImages: getAdminParams().markerImages,
    markerDefaults: { image: editorPreferences.defaults.defaultMarkerImage, rememberImage: rememberMarkerImage },
    picker: { mapId: editorPreferences.defaults.mapId ?? 0, rememberMap: rememberPickerMap, error: editorPreferences.error },
  }), [editorPreferences.defaults.mapId, editorPreferences.defaults.defaultMarkerImage, rememberMarkerImage, rememberPickerMap, editorPreferences.error])
  const baseFormContext = useMemo(
    () => ({
      [COMPLEX_FIELD_CONTEXT_KEY]: {
        media: createWordPressMediaPicker(),
        posts: createWordPressPostAdapter(),
      },
    }),
    [],
  )
  const formContext = useMemo(
    () => ({
      ...baseFormContext,
      [LOCATION_FIELD_CONTEXT_KEY]: locationAdapter,
      [COMPLEX_FIELD_CONTEXT_KEY]: {
        ...baseFormContext[COMPLEX_FIELD_CONTEXT_KEY],
        regions: regionAdapter,
      },
    }),
    [baseFormContext, regionAdapter, locationAdapter],
  )

  useEffect(() => {
    setCollectionMode("rows")
    setNewRecord(null)
    setSchemaSaveState({ dirty: false, valid: true })
  }, [schemaId])

  const handleSchemaSaveStateChange = useCallback((next: SchemaBuilderSaveState) => {
    setSchemaSaveState((current) =>
      current.dirty === next.dirty && current.valid === next.valid ? current : next,
    )
  }, [])

  useEffect(() => {
    const run = ++readRun.current
    if (!schema || postsLocked) {
      setRows([])
      setSelectedRow(null)
      setLoadingRows(false)
      setError(null)
      return
    }

    let cancelled = false
    const ownsRead = () =>
      !cancelled && current.current?.query === queryOwner && readRun.current === run
    setLoadingRows(true)
    setError(null)
    setSelectedRow(null)
    setNewRecord(null)
    setPageResult(null)
    const abort = new AbortController()

    void fetchCollectionPage(schema, pageOptions, abort.signal)
      .then((result) => {
        const nextRows = result.items
        if (ownsRead()) setPageResult(result)
        if (!ownsRead()) return
        setRows(nextRows)
        setSelectedRow(nextRows[0] ?? null)
      })
      .catch((failure) => {
        if (!ownsRead()) return
        setRows([])
        setError(failure instanceof Error ? failure.message : String(failure))
      })
      .finally(() => {
        if (ownsRead()) setLoadingRows(false)
      })

    return () => {
      cancelled = true
      abort.abort()
    }
  }, [queryOwner, schema, retry, postsLocked])

  useEffect(() => {
    if (!schema) return

    const onRepositoryMutation = (event: Event) => {
      const detail = (event as CustomEvent<{ schema?: string; action?: string }>).detail
      if (detail?.schema !== schema.name) return
      if (detail.action === "cleared" || detail.action === "deleted") {
        readRun.current++
        setRows([])
        setSelectedRow(null)
        setNewRecord(null)
        setPageResult(null)
        setLoadingRows(false)
        setError(null)
        if (detail.action === "cleared") {
          setBrowse({ key: browseKey, pageIndex: 0, search: "" })
          setRetry((value) => value + 1)
        }
        return
      }
      const run = ++readRun.current
      const ownsCollectionRead = () =>
        current.current?.query === queryOwner && readRun.current === run
      const ownsRead = () => ownsCollectionRead() && current.current?.view === owner
      void fetchCollectionPage(schema, pageOptions)
        .then((result) => {
          if (!ownsCollectionRead()) return
          const nextRows = result.items
          setPageResult(result)
          setRows(nextRows)
          if (!ownsRead()) {
            // Retain valid Collection data when the view changed during this
            // read, without replacing an existing record's unsaved draft.
            if (!current.current?.creating) {
              setSelectedRow((selected) => selected ?? nextRows[0] ?? null)
            }
            return
          }
          setSelectedRow((current) => {
            const id = current?.id
            if (id == null) return nextRows[0] ?? null
            return nextRows.find((row) => String(row.id) === String(id)) ?? nextRows[0] ?? null
          })
          setError(null)
        })
        .catch((failure) => {
          if (ownsCollectionRead()) {
            setPageResult(null)
            setError(failure instanceof Error ? failure.message : String(failure))
          }
        })
        .finally(() => {
          // This read may have replaced the initial load, then lost its row/view
          // owner. It still owns completion of that Collection's loading state.
          if (ownsCollectionRead()) setLoadingRows(false)
        })
    }

    window.addEventListener("mapsvg:repository-mutation", onRepositoryMutation)
    return () => window.removeEventListener("mapsvg:repository-mutation", onRepositoryMutation)
  }, [owner, schema, queryOwner])

  const beginMutation = () => {
    const run = ++mutationRun.current
    let refreshRun: number | null = null
    return {
      ownsMutation: () =>
        current.current?.view === owner &&
        mutationRun.current === run &&
        (refreshRun === null || readRun.current === refreshRun),
      beginRead: () => {
        refreshRun = ++readRun.current
      },
    }
  }

  const createRow = async (record: DataRow) => {
    if (!schema || !pageResult?.capabilities.canCreate || recordMutation === owner) return
    const { ownsMutation, beginRead } = beginMutation()
    setRecordMutation(owner)
    setError(null)
    try {
      const created = await createCollectionRow(schema, record)
      if (!ownsMutation()) return
      beginRead()
      const result = await fetchCollectionPage(schema, pageOptions)
      if (!ownsMutation()) return
      const nextRows = result.items
      setPageResult(result)
      const id = created.id
      setRows(nextRows)
      setSelectedRow(
        id == null
          ? (nextRows[0] ?? created)
          : (nextRows.find((row) => String(row.id) === String(id)) ?? created),
      )
      setNewRecord(null)
    } catch (failure) {
      if (!ownsMutation()) return
      if (!isRecordValidationError(failure)) {
        setPageResult(null)
        setError(failure instanceof Error ? failure.message : String(failure))
      }
      throw failure
    } finally {
      setRecordMutation((pending) => pending === owner ? null : pending)
    }
  }

  const saveSelectedRow = async (record: DataRow) => {
    if (!schema || !pageResult?.capabilities.canEdit || recordMutation === owner) return
    const { ownsMutation, beginRead } = beginMutation()
    setRecordMutation(owner)
    setError(null)
    try {
      await updateCollectionRow(schema, record)
      if (!ownsMutation()) return
      beginRead()
      const result = await fetchCollectionPage(schema, pageOptions)
      if (!ownsMutation()) return
      const nextRows = result.items
      setPageResult(result)
      setRows(nextRows)
      const id = record.id
      setSelectedRow(
        id == null
          ? (nextRows[0] ?? null)
          : (nextRows.find((row) => String(row.id) === String(id)) ?? nextRows[0] ?? null),
      )
    } catch (failure) {
      if (!ownsMutation()) return
      if (!isRecordValidationError(failure)) {
        setPageResult(null)
        setError(failure instanceof Error ? failure.message : String(failure))
      }
      throw failure
    } finally {
      setRecordMutation((pending) => pending === owner ? null : pending)
    }
  }

  const deleteSelectedRow = async () => {
    if (!schema || !pageResult?.capabilities.canDelete || recordMutation === owner || selectedRow?.id == null) return
    if (!window.confirm("Delete this record?")) return
    const { ownsMutation, beginRead } = beginMutation()
    const id = selectedRow.id
    setRecordMutation(owner)
    setError(null)
    try {
      await deleteCollectionRow(schema, id as string | number)
      if (!ownsMutation()) return
      beginRead()
      const result = await fetchCollectionPage(schema, pageOptions)
      if (!ownsMutation()) return
      setPageResult(result)
      setRows(result.items)
      setSelectedRow(result.items[0] ?? null)
      if (pageIndex > 0 && result.items.length === 0) {
        setBrowse({ key: browseKey, search, pageIndex: Math.max(0, result.count === null ? pageIndex - 1 : Math.ceil(result.count / 50) - 1) })
      }
    } catch (failure) {
      if (ownsMutation()) {
        setPageResult(null)
        setError(failure instanceof Error ? failure.message : String(failure))
      }
    } finally {
      setRecordMutation((pending) => pending === owner ? null : pending)
    }
  }

  const saveSchemaFields = async (fields: FormFieldData[], zodSettings: ZodSettings | null) => {
    if (!schema) return
    const { ownsMutation } = beginMutation()
    setError(null)
    try {
      await updateSchemaFields(schema, fields as SchemaField[], zodSettings)
      if (!ownsMutation()) return
      await refreshSchemas(ownsMutation)
    } catch (failure) {
      if (!ownsMutation()) return
      setError(failure instanceof Error ? failure.message : String(failure))
      throw failure
    }
  }

  if (postsLocked) return <ProductFeaturePlaceholder feature="data_source_posts" />
  if (!schemaId) {
    return (
      <div className="flex min-h-0 min-w-0 flex-1 items-center justify-center p-6">
        <p className="text-sm text-muted-foreground">Select a table from Database.</p>
      </div>
    )
  }

  if (loadingSchemas && !schema) {
    return (
      <div className="flex min-h-0 min-w-0 flex-1 items-center justify-center p-6">
        <p className="text-sm text-muted-foreground">Loading table…</p>
      </div>
    )
  }

  if (!schema) {
    return (
      <div className="flex min-h-0 min-w-0 flex-1 items-center justify-center p-6">
        <p className="text-sm text-destructive">{schemaError ?? "This table is unavailable."}</p>
      </div>
    )
  }

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden bg-background">
      <header
        data-slot="database-toolbar"
        className="grid h-10 shrink-0 grid-cols-[minmax(0,1fr)_minmax(0,1fr)_minmax(0,1fr)] items-center gap-2 border-b border-border px-2"
      >
        <div className="min-w-0 justify-self-start">
          <div className="flex rounded-md border p-0.5" role="tablist" aria-label="Collection view">
            {(["rows", "fields", "import", "settings"] as const).map((mode) => (
              <button
                key={mode}
                type="button"
                role="tab"
                aria-selected={collectionMode === mode}
                onClick={() => {
                  setNewRecord(null)
                  setCollectionMode(mode)
                }}
                className={cn(
                  "rounded px-2 py-0.5 text-xs capitalize",
                  collectionMode === mode ? "bg-accent font-medium" : "text-muted-foreground",
                )}
              >
                {mode === "rows" ? "Data" : mode === "fields" ? "Fields" : mode === "import" ? "Import" : "Settings"}
              </button>
            ))}
          </div>
        </div>
        <div data-slot="database-title" className="flex min-w-0 items-center justify-center gap-1.5 overflow-hidden text-xs">
          <span className="shrink-0 text-muted-foreground">Collection</span>
          <span className="truncate font-medium">{schemaDisplayTitle(schema)}</span>
        </div>
        <div className="flex min-w-0 items-center justify-end">
          {collectionMode === "rows" ? (
            <Button
              type="button"
              size="xs"
              variant="outline"
              disabled={loadingRows || creatingRow || !pageResult?.capabilities.canCreate || recordMutation === owner}
              onClick={() => {
                setError(null)
                setNewRecord({ collection: collectionOwner, value: {} })
              }}
            >
              <PlusIcon />
              Add record
            </Button>
          ) : collectionMode === "fields" ? (
            <Button
              type="submit"
              form={COLLECTION_SCHEMA_FORM_ID}
              size="xs"
              disabled={!schemaSaveState.dirty || !schemaSaveState.valid}
            >
              <SaveIcon />
              Publish schema
            </Button>
          ) : null}
        </div>
      </header>

      {error ? (
        <div
          role="alert"
          className="shrink-0 border-b border-destructive/20 bg-destructive/5 px-3 py-2 text-sm text-destructive"
        >
          {error}
          {collectionMode === "rows" ? <Button variant="outline" size="xs" onClick={() => setRetry((value) => value + 1)}>Retry records</Button> : null}
        </div>
      ) : null}

      {collectionMode === "rows" && pageResult?.capabilities.reason ? <p className="border-b px-3 py-2 text-sm text-muted-foreground">{pageResult.capabilities.reason}</p> : null}

      {collectionMode === "settings" ? (
        <CollectionSettings key={`${schema.id}:${schemaKey}`} schema={schema} refreshCatalog={refreshSchemas} />
      ) : collectionMode === "import" ? (
        importEnabled ? <DatabaseCsvImport key={String(schema.id)} schema={schema} onSchemaSaved={refreshSchemas} /> : <ProductFeaturePlaceholder feature="csv" />
      ) : collectionMode === "fields" ? (
        <div className="min-h-0 flex-1 p-3">
          <SchemaBuilder
            className="h-full"
            fields={editableFields}
            hiddenFieldNames={schema.type === "region" ? ["orphaned"] : undefined}
            zodSettings={schema.zodSettings ?? null}
            settingsContext={formContext}
            onSave={saveSchemaFields}
            formId={COLLECTION_SCHEMA_FORM_ID}
            showSaveButton={false}
            onSaveStateChange={handleSchemaSaveStateChange}
          />
        </div>
      ) : (
        <div className="grid min-h-0 min-w-0 flex-1 grid-cols-2 overflow-hidden">
          <section className="min-h-0 min-w-0 overflow-hidden border-r border-border">
            <DataListTable
              variant="pane"
              schema={schema}
              rows={rows}
              loading={loadingRows}
              serverState={{ pageIndex, pageSize: 50, count: pageResult ? pageResult.count : 0, hasMore: pageResult?.hasMore, search, loading: loadingRows,
                onSearchChange: (value) => setBrowse({ key: browseKey, pageIndex: 0, search: value }),
                onPageChange: (value) => setBrowse({ key: browseKey, pageIndex: value, search }),
              }}
              readOnly
              selectedRow={selectedRow}
              onRowClick={(row) => {
                if (loadingRows || !pageResult) return
                setNewRecord(null)
                setSelectedRow(row)
              }}
            />
          </section>
          <section className="flex min-h-0 min-w-0 flex-col overflow-hidden bg-muted">
            <header className="flex h-10 shrink-0 items-center border-b border-border bg-background px-3">
              <span className="min-w-0 truncate text-sm font-medium">
                {creatingRow
                  ? "New row"
                  : selectedRow?.id != null
                    ? `Edit row #${selectedRow.id}`
                    : "Row editor"}
              </span>
              {!creatingRow && selectedRow ? <div className="ml-auto flex items-center gap-1">
                <Tooltip><TooltipTrigger asChild><span className="inline-flex"><Button type="button" size="icon-xs" variant="ghost" aria-label="Duplicate record"
                  disabled={loadingRows || !pageResult?.capabilities.canCreate || recordMutation === owner}
                  onClick={() => {
                    if (!schema || !selectedRow || loadingRows || !pageResult?.capabilities.canCreate || recordMutation === owner) return
                    setError(null)
                    setNewRecord({ collection: collectionOwner, value: duplicateCollectionRecord(schema, selectedRow) })
                  }}><CopyPlusIcon /></Button></span></TooltipTrigger><TooltipContent>Duplicate record</TooltipContent></Tooltip>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="inline-flex">
                      <Button type="button" size="icon-xs" variant="ghost" aria-label="Delete record" disabled={loadingRows || !pageResult?.capabilities.canDelete || recordMutation === owner} onClick={() => void deleteSelectedRow()}><Trash2Icon /></Button>
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>Delete record</TooltipContent>
                </Tooltip>
              </div> : null}
              {creatingRow ? (
                <Button
                  type="button"
                  size="xs"
                  variant="ghost"
                  className="ml-auto"
                  onClick={() => setNewRecord(null)}
                >
                  Cancel
                </Button>
              ) : null}
            </header>
            <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
              {creatingRow || selectedRow ? (
                <SchemaForm
                  variant="pane"
                  key={
                    creatingRow
                      ? `new:${schema.id}`
                      : `${schema.id}:${String(selectedRow?.id ?? "")}`
                  }
                  schema={{
                    fields: editableFields,
                    zodSettings: schema.zodSettings ?? null,
                  }}
                  value={creatingRow ? newRecord!.value : (selectedRow ?? EMPTY_NEW_ROW)}
                  mode={creatingRow ? "create" : "edit"}
                  controlContext={formContext}
                  submitLabel={creatingRow ? "Create row" : "Save row"}
                  disabled={loadingRows || recordMutation === owner || !(creatingRow ? pageResult?.capabilities.canCreate : pageResult?.capabilities.canEdit)}
                  onSubmit={(creatingRow ? pageResult?.capabilities.canCreate : pageResult?.capabilities.canEdit) ? (creatingRow ? createRow : saveSelectedRow) : undefined}
                />
              ) : (
                <p className="p-3 text-sm text-muted-foreground">Select a row to edit its fields.</p>
              )}
            </div>
          </section>
        </div>
      )}
    </div>
  )
}
