import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { recordSchemaKey, useCollectionEditorDefaults } from "@/lib/collection-editor-defaults"
import { DataListTable } from "@/components/data/DataListTable"
import { GlobalQuerySettings } from "@/components/database/GlobalQuerySettings"
import { savedQueryContentKey } from "@/components/database/globalQueryDraft"
import {
  createCollectionRegionAdapter,
  regionCatalogKey,
} from "@/components/form-builder/complex-fields/collectionRegionAdapter"
import { useDatabaseNavigation } from "@/components/database/database-navigation-context"
import {
  COMPLEX_FIELD_CONTEXT_KEY,
  createWordPressMediaPicker,
  createWordPressPostAdapter,
} from "@/components/form-builder/complex-fields"
import {
  LOCATION_FIELD_CONTEXT_KEY,
  createStandaloneLocationAdapter,
} from "@/components/form-builder/location-field"
import { SchemaForm } from "@/components/form-builder/schema-form"
import { Button } from "@/components/ui/button"
import { getAdminParams } from "@/lib/admin-params"
import {
  deleteGlobalQuery,
  executeGlobalQuery,
  fetchCollectionPage,
  fetchCollectionRow,
  saveGlobalQuery,
  updateCollectionRow,
  type GlobalQueryDraft,
  type CollectionCapabilities,
} from "@/lib/mapsvg-api"
import { isRecordValidationError } from "@/lib/record-validation-error"
import { cn } from "@/lib/utils"
import type { FormFieldData } from "../../../../mapsvg/FormBuilder/FieldDefinitions"

type DataRow = Record<string, unknown>
type QueryViewMode = "data" | "settings"

export function DatabaseQueriesWorkspace({ initialMode = "data" }: { initialMode?: QueryViewMode }) {
  const {
    schemas,
    folders,
    queries,
    queriesEnabled,
    selectedQueryId,
    setSelectedQueryId,
    refreshQueries,
    creatingQuery,
    newQueryFolderId,
    cancelQueryCreation,
  } = useDatabaseNavigation()

  const [mode, setMode] = useState<QueryViewMode>(initialMode)
  useEffect(() => setMode(initialMode), [initialMode])

  const selectedQuery = queries.find((query) => query.id === selectedQueryId) ?? null
  const pageSize = selectedQuery?.input.take && Number.isInteger(selectedQuery.input.take)
    ? Math.max(1, Math.min(250, selectedQuery.input.take)) : 50
  const querySchema = selectedQuery
    ? (schemas.find((schema) => Number(schema.id) === selectedQuery.schemaId) ?? null)
    : null
  const editorPreferences = useCollectionEditorDefaults(querySchema)
  // Result state belongs to the selected Query and its resolved Collection, not
  // to the workspace component's lifetime. A new owner starts on the first page.
  const viewKey = JSON.stringify([
    queriesEnabled,
    creatingQuery,
    newQueryFolderId,
    selectedQueryId,
    savedQueryContentKey(selectedQuery),
    recordSchemaKey(querySchema),
  ])
  const [pageState, setPageState] = useState({ key: viewKey, page: 0 })
  const page = pageState.key === viewKey ? pageState.page : 0
  useLayoutEffect(() => {
    setPageState((previous) => (previous.key === viewKey ? previous : { key: viewKey, page: 0 }))
  }, [viewKey])
  const [resultState, setResultState] = useState<{
    key: string
    rows: DataRow[]
    count: number
    selected: DataRow | null
    loading: boolean
    error: string | null
  }>({ key: viewKey, rows: [], count: 0, selected: null, loading: false, error: null })
  const result =
    resultState.key === viewKey
      ? resultState
      : {
          key: viewKey,
          rows: [],
          count: 0,
          selected: null,
          loading: false,
          error: null,
        }
  const { rows, count: rowCount, selected: selectedRow, loading: loadingRows, error } = result
  const owner = useMemo(() => ({}), [viewKey, mode, page])
  const current = useRef<{ owner: object; page: number; selected: DataRow | null } | null>(null)
  const readAbort = useRef<AbortController | null>(null)
  const readRun = useRef(0)
  const mutationRun = useRef(0)
  useLayoutEffect(() => {
    if (current.current && current.current.selected !== selectedRow) mutationRun.current++
    current.current = { owner, page, selected: selectedRow }
  })
  useLayoutEffect(
    () => () => {
      current.current = null
      readAbort.current?.abort()
      readRun.current++
      mutationRun.current++
    },
    [owner],
  )
  const updateResult = (patch: Partial<Omit<typeof resultState, "key">>) => {
    setResultState((previous) => ({
      ...(previous.key === viewKey
        ? previous
        : {
            key: viewKey,
            rows: [],
            count: 0,
            selected: null,
            loading: false,
            error: null,
          }),
      ...patch,
    }))
  }
  const setPage = (next: number | ((previous: number) => number)) => {
    setPageState((previous) => ({
      key: viewKey,
      page: typeof next === "function" ? next(previous.key === viewKey ? previous.page : 0) : next,
    }))
  }
  const setSelectedRow = (selected: DataRow | null) => updateResult({ selected })
  const editableFields = useMemo(
    () => (querySchema?.fields ?? []) as FormFieldData[],
    [querySchema],
  )

  const sourcesKey = regionCatalogKey(schemas)
  const rememberRegionSource = useCallback((name: string) => editorPreferences.remember({ regionsTableName: name }), [editorPreferences.remember])
  const rememberPickerMap = useCallback((mapId: number) => editorPreferences.remember({ mapId }), [editorPreferences.remember])
  const rememberMarkerImage = useCallback((defaultMarkerImage: string) => editorPreferences.remember({ defaultMarkerImage }), [editorPreferences.remember])
  const regionAdapter = useMemo(() => createCollectionRegionAdapter(schemas, {
    tableName: editorPreferences.defaults.regionsTableName ?? "", rememberSource: rememberRegionSource, preferenceKey: String(querySchema?.id), preferenceError: editorPreferences.error,
  }), [sourcesKey, editorPreferences.defaults.regionsTableName, rememberRegionSource, querySchema?.id, editorPreferences.error])
  const locationAdapter = useMemo(() => createStandaloneLocationAdapter({ markerImages: getAdminParams().markerImages,
    markerDefaults: { image: editorPreferences.defaults.defaultMarkerImage, rememberImage: rememberMarkerImage },
    picker: { mapId: editorPreferences.defaults.mapId ?? 0, rememberMap: rememberPickerMap, error: editorPreferences.error },
  }), [editorPreferences.defaults.mapId, editorPreferences.defaults.defaultMarkerImage, rememberMarkerImage, rememberPickerMap, editorPreferences.error])
  const baseFormContext = useMemo(
    () => ({
      [COMPLEX_FIELD_CONTEXT_KEY]: {
        media: createWordPressMediaPicker(),
        posts: createWordPressPostAdapter(),
      },
    }),
    [],
  )
  const formContext = useMemo(
    () => ({
      ...baseFormContext,
      [LOCATION_FIELD_CONTEXT_KEY]: locationAdapter,
      [COMPLEX_FIELD_CONTEXT_KEY]: {
        ...baseFormContext[COMPLEX_FIELD_CONTEXT_KEY],
        regions: regionAdapter,
      },
    }),
    [baseFormContext, regionAdapter, locationAdapter],
  )

  useEffect(() => {
    if (creatingQuery) setMode("settings")
  }, [creatingQuery])

  useEffect(() => {
    const run = ++readRun.current
    readAbort.current?.abort()
    const controller = new AbortController()
    readAbort.current = controller
    const ownsRead = () =>
      current.current?.owner === owner && current.current.page === page && readRun.current === run
    if (!queriesEnabled || !selectedQuery || !querySchema || creatingQuery || mode !== "data") {
      updateResult({ loading: false, error: null })
      return
    }
    updateResult({ loading: true, error: null, rows: [], count: 0, selected: null })
    void executeGlobalQuery(selectedQuery.id, { skip: page * pageSize, take: pageSize }, controller.signal)
      .then((next) => {
        if (!ownsRead()) return
        updateResult({ rows: next.rows, count: next.count, selected: next.rows[0] ?? null })
      })
      .catch((failure) => {
        if (!ownsRead()) return
        updateResult({
          rows: [],
          count: 0,
          selected: null,
          error: failure instanceof Error ? failure.message : String(failure),
        })
      })
      .finally(() => {
        if (ownsRead()) updateResult({ loading: false })
      })
    return () => {
      controller.abort()
      if (readRun.current === run) readRun.current++
    }
  }, [creatingQuery, mode, page, owner, queriesEnabled])

  // A Query projection is for browsing only. The full Collection record owns
  // the editor's validation and values, including fields omitted by select.
  const [recordRetry, setRecordRetry] = useState(0)
  const [capabilityState, setCapabilityState] = useState<{
    owner: object
    capabilities: CollectionCapabilities | null
    error: string | null
  } | null>(null)
  const sourcePolicy = capabilityState?.owner === owner ? capabilityState : null
  useEffect(() => {
    if (!querySchema || mode !== "data" || creatingQuery || !queriesEnabled) return
    const controller = new AbortController()
    let active = true
    const commit = (capabilities: CollectionCapabilities | null, error: string | null) => {
      if (active && current.current?.owner === owner) {
        setCapabilityState({ owner, capabilities, error })
      }
    }
    commit(null, null)
    void fetchCollectionPage(querySchema, { page: 1, perpage: 1, search: "" }, controller.signal)
      .then((result) => commit(result.capabilities, null))
      .catch((failure) =>
        commit(null, failure instanceof Error ? failure.message : String(failure)),
      )
    return () => {
      active = false
      controller.abort()
    }
  }, [owner, recordRetry])
  const [recordState, setRecordState] = useState<{
    owner: object
    selection: DataRow | null
    row: DataRow | null
    loading: boolean
    error: string | null
  } | null>(null)
  const editorRecord =
    recordState?.owner === owner && recordState.selection === selectedRow ? recordState : null
  useEffect(() => {
    if (!selectedRow || !querySchema || mode !== "data" || creatingQuery || !queriesEnabled) return
    const selection = selectedRow
    const controller = new AbortController()
    let active = true
    const ownsRead = () =>
      active && current.current?.owner === owner && current.current.selected === selection
    const commit = (row: DataRow | null, loading: boolean, error: string | null) => {
      if (ownsRead()) setRecordState({ owner, selection, row, loading, error })
    }
    const id = selection.id
    if (
      (typeof id !== "string" && typeof id !== "number") ||
      id === "" ||
      (typeof id === "number" && !Number.isFinite(id))
    ) {
      commit(
        null,
        false,
        "This result has no record id. Include id in the Query projection to edit it.",
      )
    } else {
      commit(null, true, null)
      void fetchCollectionRow(querySchema, id, controller.signal)
        .then((row) => commit(row, false, null))
        .catch((failure) =>
          commit(null, false, failure instanceof Error ? failure.message : String(failure)),
        )
    }
    return () => {
      active = false
      controller.abort()
    }
  }, [owner, selectedRow, recordRetry])

  const saveQuery = async (draft: GlobalQueryDraft) => {
    const run = ++mutationRun.current
    const ownsMutation = () => current.current?.owner === owner && mutationRun.current === run
    try {
      const saved = await saveGlobalQuery(draft)
      if (!ownsMutation()) return
      await refreshQueries(ownsMutation, () => {
        if (!ownsMutation()) return
        setSelectedQueryId(saved.id)
        setPage(0)
        cancelQueryCreation()
        setMode("data")
      })
    } catch (failure) {
      if (ownsMutation()) throw failure
    }
  }

  const removeQuery = async (id: string) => {
    const run = ++mutationRun.current
    const ownsMutation = () => current.current?.owner === owner && mutationRun.current === run
    try {
      await deleteGlobalQuery(id)
      if (!ownsMutation()) return
      await refreshQueries(ownsMutation, (next) => {
        if (!ownsMutation()) return
        setSelectedQueryId(next[0]?.id ?? null)
        setPage(0)
        setMode("data")
      })
    } catch (failure) {
      if (ownsMutation()) throw failure
    }
  }

  const saveSelectedRow = async (record: DataRow) => {
    if (!querySchema || !selectedQuery || !editorRecord?.row) return
    if (!sourcePolicy?.capabilities?.canEdit) {
      throw new Error(sourcePolicy?.capabilities?.reason ?? "Collection editing is unavailable.")
    }
    if (String(record.id) !== String(editorRecord.row.id)) {
      throw new Error("The edited record id does not match the selected source row.")
    }
    const run = ++mutationRun.current
    const selection = selectedRow
    const ownsMutation = () =>
      current.current?.owner === owner &&
      current.current.page === page &&
      current.current.selected === selection &&
      mutationRun.current === run
    updateResult({ error: null })
    try {
      await updateCollectionRow(querySchema, record)
      if (!ownsMutation()) return
      const refresh = ++readRun.current
      readAbort.current?.abort()
      const controller = new AbortController()
      readAbort.current = controller
      const next = await executeGlobalQuery(
        selectedQuery.id,
        { skip: page * pageSize, take: pageSize },
        controller.signal,
      )
      if (!ownsMutation() || readRun.current !== refresh) return
      const id = record.id
      updateResult({
        rows: next.rows,
        count: next.count,
        selected:
          id == null
            ? (next.rows[0] ?? null)
            : (next.rows.find((row) => String(row.id) === String(id)) ?? next.rows[0] ?? null),
      })
    } catch (failure) {
      if (!ownsMutation()) return
      if (!isRecordValidationError(failure)) {
        updateResult({ error: failure instanceof Error ? failure.message : String(failure) })
      }
      throw failure
    }
  }

  if (!queriesEnabled) {
    return (
      <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden bg-background">
        <header data-slot="database-toolbar" className="flex h-10 shrink-0 items-center justify-center gap-1.5 border-b border-border px-2 text-xs">
          <span className="font-medium">Queries</span>
        </header>
        <p className="p-4 text-sm text-muted-foreground">
          Queries require Data Layer v2 and Global Queries to be enabled.
        </p>
      </div>
    )
  }

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden bg-background">
      <header
        data-slot="database-toolbar"
        className="grid h-10 shrink-0 grid-cols-[minmax(0,1fr)_minmax(0,1fr)_minmax(0,1fr)] items-center gap-2 border-b border-border px-2"
      >
        <div className="min-w-0 justify-self-start">
          {selectedQuery && !creatingQuery ? (
            <div className="flex rounded-md border p-0.5" role="tablist" aria-label="Query view">
              {(["data", "settings"] as const).map((nextMode) => (
                <button
                  key={nextMode}
                  type="button"
                  role="tab"
                  aria-selected={mode === nextMode}
                  onClick={() => setMode(nextMode)}
                  className={cn(
                    "rounded px-2 py-0.5 text-xs capitalize",
                    mode === nextMode ? "bg-accent font-medium" : "text-muted-foreground",
                  )}
                >
                  {nextMode === "data" ? "Data" : "Settings"}
                </button>
              ))}
            </div>
          ) : null}
        </div>
        <div data-slot="database-title" className="flex min-w-0 items-center justify-center gap-1.5 overflow-hidden text-xs">
          {!creatingQuery && selectedQuery ? <span className="shrink-0 text-muted-foreground">Query</span> : null}
          <span className="truncate font-medium">{creatingQuery ? "New query" : selectedQuery?.name ?? "Queries"}</span>
        </div>
      </header>

      {error ? (
        <div
          role="alert"
          className="shrink-0 border-b border-destructive/20 bg-destructive/5 px-3 py-2 text-sm text-destructive"
        >
          {error}
        </div>
      ) : null}

      {creatingQuery || (selectedQuery && mode === "settings") ? (
        <div className="min-h-0 flex-1 overflow-auto">
          <GlobalQuerySettings
            key={creatingQuery ? `new-${newQueryFolderId}` : selectedQuery?.id}
            schemas={schemas}
            folders={folders}
            query={creatingQuery ? null : selectedQuery}
            initialFolderId={newQueryFolderId}
            onSave={saveQuery}
            onDelete={removeQuery}
            onCancel={() => {
              cancelQueryCreation()
              setMode("data")
            }}
          />
        </div>
      ) : !selectedQuery ? (
        <p className="p-4 text-sm text-muted-foreground">Select a query or create one.</p>
      ) : !querySchema ? (
        <p className="p-4 text-sm text-destructive">
          The linked collection is unavailable. Open Settings to select another collection.
        </p>
      ) : (
        <div className="grid min-h-0 min-w-0 flex-1 grid-cols-2 overflow-hidden">
          <section className="min-h-0 min-w-0 overflow-hidden border-r border-border">
            <DataListTable
              variant="pane"
              paginationState={{ pageIndex: page, pageSize, count: rowCount, onPageChange: setPage, loading: loadingRows }}
              schema={querySchema}
              rows={rows}
              loading={loadingRows}
              readOnly
              selectedRow={selectedRow}
              onRowClick={setSelectedRow}
            />
          </section>
          <section className="flex min-h-0 min-w-0 flex-col overflow-hidden bg-muted">
            <header className="flex h-10 shrink-0 items-center border-b border-border bg-background px-3">
              <span className="text-sm font-medium">
                {selectedRow?.id != null ? `Edit row #${selectedRow.id}` : "Row editor"}
              </span>
            </header>
            <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
              {selectedRow && sourcePolicy?.error ? (
                <div role="alert" className="overflow-auto p-3 space-y-2 text-sm">
                  <p>{sourcePolicy.error}</p>
                  <Button variant="outline" onClick={() => setRecordRetry((retry) => retry + 1)}>
                    Retry source permissions
                  </Button>
                </div>
              ) : selectedRow && editorRecord?.row && sourcePolicy?.capabilities ? (
                <>
                  {!sourcePolicy.capabilities.canEdit ? (
                    <p role="status" className="shrink-0 p-3 text-sm text-muted-foreground">
                      {sourcePolicy.capabilities.reason ?? "This Collection is read-only."}
                    </p>
                  ) : null}
                  <SchemaForm
                    variant="pane"
                    key={`${viewKey}:${String(selectedRow.id ?? "")}`}
                    schema={{
                      fields: editableFields,
                      zodSettings: querySchema.zodSettings ?? null,
                    }}
                    value={editorRecord.row}
                    mode="edit"
                    controlContext={formContext}
                    submitLabel="Save row"
                    disabled={!sourcePolicy.capabilities.canEdit}
                    onSubmit={sourcePolicy.capabilities.canEdit ? saveSelectedRow : undefined}
                  />
                </>
              ) : selectedRow ? (
                editorRecord?.error ? (
                  <div role="alert" className="overflow-auto p-3 space-y-2 text-sm">
                    <p>{editorRecord.error}</p>
                    <Button variant="outline" onClick={() => setRecordRetry((retry) => retry + 1)}>
                      Retry source row
                    </Button>
                  </div>
                ) : (
                  <p role="status" className="p-3 text-sm text-muted-foreground">
                    Loading source row…
                  </p>
                )
              ) : (
                <p className="p-3 text-sm text-muted-foreground">Select a row to edit its fields.</p>
              )}
            </div>
          </section>
        </div>
      )}
    </div>
  )
}
