import { useLayoutEffect, useState } from "react"
import { DatabaseQueriesWorkspace } from "@/components/database/DatabaseQueriesWorkspace"
import { DatabaseSecondarySidebar } from "@/components/database/DatabaseSecondarySidebar"
import { DatabaseTableWorkspace } from "@/components/database/DatabaseTableWorkspace"
import { useDatabaseNavigation } from "@/components/database/database-navigation-context"
import type { DataSchema, GlobalSavedQuery } from "@/lib/mapsvg-api"

type Props = {
  initialQuerySettings?: boolean
  selectedSchemaId: string | null
  onSelectSchema: (schema: DataSchema) => void
  onSelectQuery?: (query: GlobalSavedQuery) => void
  onOpenSchemaTab?: (schema: DataSchema) => void
  onOpenQueryTab?: (query: GlobalSavedQuery) => void
  onOpenQueries: () => void
  onCatalogReady?: (schemas: DataSchema[], queries: GlobalSavedQuery[]) => void
  onQueryCatalogReady?: (queries: GlobalSavedQuery[]) => void
}

export function DatabaseWorkspace({
  initialQuerySettings = false,
  selectedSchemaId,
  onSelectSchema,
  onSelectQuery,
  onOpenSchemaTab,
  onOpenQueryTab,
  onOpenQueries,
  onCatalogReady,
  onQueryCatalogReady,
}: Props) {
  const { section, setSection, schemas, schemasLoaded, loading, error } = useDatabaseNavigation()
  const [rememberedSchemaId, setRememberedSchemaId] = useState(selectedSchemaId)
  const rememberedSchema = schemas.find((schema) => String(schema.id) === rememberedSchemaId)
  const effectiveSchemaId = selectedSchemaId ?? (rememberedSchema ? rememberedSchemaId : null)

  useLayoutEffect(() => {
    if (selectedSchemaId != null) {
      setRememberedSchemaId(selectedSchemaId)
      setSection("collections")
    }
  }, [selectedSchemaId, setSection])

  useLayoutEffect(() => {
    if (schemasLoaded && !loading && !error && rememberedSchemaId && !rememberedSchema) {
      setRememberedSchemaId(null)
    }
  }, [schemasLoaded, loading, error, rememberedSchemaId, rememberedSchema])

  return (
    <div className="flex min-h-0 min-w-0 flex-1 overflow-hidden">
      <DatabaseSecondarySidebar
        selectedSchemaId={effectiveSchemaId}
        onSelectSchema={onSelectSchema}
        onSelectQuery={onSelectQuery}
        onOpenSchemaTab={onOpenSchemaTab}
        onOpenQueryTab={onOpenQueryTab}
        onSectionChange={(next) => {
          if (next === "queries") onOpenQueries()
          else if (
            selectedSchemaId === null &&
            schemasLoaded &&
            !loading &&
            !error &&
            rememberedSchema
          ) {
            onSelectSchema(rememberedSchema)
          }
        }}
        onCatalogReady={onCatalogReady}
        onQueryCatalogReady={onQueryCatalogReady}
      />
      {section === "queries" ? (
        <DatabaseQueriesWorkspace initialMode={initialQuerySettings ? "settings" : "data"} />
      ) : (
        <DatabaseTableWorkspace schemaId={effectiveSchemaId} />
      )}
    </div>
  )
}
