import { useLayoutEffect, useRef, useState } from "react"
import { toast } from "sonner"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { getAdminParams } from "@/lib/admin-params"
import {
  clearCollection,
  deleteCollection,
  updateCollectionSettings,
  schemaDisplayTitle,
  type CollectionSettingsValue,
  type DataSchema,
} from "@/lib/mapsvg-api"

type Action = "save" | "clear" | "delete"
type Props = {
  schema: DataSchema
  refreshCatalog: (current: () => boolean) => Promise<unknown>
}
const flag = (value: unknown, fallback: boolean) =>
  value == null
    ? fallback
    : value === true ||
      value === 1 ||
      ["true", "1", "yes", "on"].includes(String(value).toLowerCase())

/** Mount with the schema content key: a replaced source/schema retires every continuation. */
export function CollectionSettings({ schema, refreshCatalog }: Props) {
  const [draft, setDraft] = useState<CollectionSettingsValue>(() => ({
    title: schema.title ?? "",
    objectNameSingular: schema.objectNameSingular ?? "",
    objectNamePlural: schema.objectNamePlural ?? "",
    markerSupport: flag(schema.markerSupport, true),
    regionSupport: flag(schema.regionSupport, false),
  }))
  const [confirmation, setConfirmation] = useState<"clear" | "delete" | null>(null)
  const [busy, setBusy] = useState(false)
  const [committed, setCommitted] = useState<Action | null>(null)
  const [error, setError] = useState<string | null>(null)
  const life = useRef<object | null>(null)
  const pending = useRef(false)
  useLayoutEffect(() => {
    const owner = {}
    life.current = owner
    return () => {
      if (life.current === owner) life.current = null
    }
  }, [])
  const canManage = getAdminParams().user?.isAdmin === true
  const canClear = schema.type !== "api"
  const canDelete = schema.type !== "region" && !schema.bindings?.svg
  const locked = !canManage || busy || !!committed
  const update = (value: Partial<CollectionSettingsValue>) => {
    if (!locked) {
      setDraft((current) => ({ ...current, ...value }))
      setError(null)
    }
  }

  const run = async (requested: Action) => {
    const owner = life.current
    if (!owner || pending.current || !canManage) return
    const action = committed ?? requested
    if (!committed) {
      if ((action === "clear" && !canClear) || (action === "delete" && !canDelete)) return
      if (action === "save") {
        if (
          !draft.title.trim() ||
          !draft.objectNameSingular.trim() ||
          !draft.objectNamePlural.trim()
        ) {
          setError("Enter a title, singular name and plural name.")
          return
        }
        if (schema.type === "post" && !draft.markerSupport && !draft.regionSupport) {
          setError("Enable Marker support and/or Region support.")
          return
        }
      }
    }
    pending.current = true
    const current = () => life.current === owner
    setBusy(true)
    setError(null)
    try {
      if (!committed) {
        if (action === "save") await updateCollectionSettings(schema, { ...draft })
        else if (action === "clear") await clearCollection(schema)
        else await deleteCollection(schema)
        if (!current()) return
        window.dispatchEvent(
          new CustomEvent("mapsvg:repository-mutation", {
            detail: {
              schema: schema.name,
              action: action === "clear" ? "cleared" : action === "delete" ? "deleted" : "updated",
            },
          }),
        )
        toast.success(
          action === "save"
            ? "Collection settings saved."
            : action === "clear"
              ? "Table cleared."
              : "Collection deleted.",
        )
        if (action === "clear") {
          setConfirmation(null)
          return
        }
        setCommitted(action)
      }
      await refreshCatalog(current)
      if (!current()) return
      setCommitted(null)
      setConfirmation(null)
    } catch (failure) {
      if (current()) setError(failure instanceof Error ? failure.message : String(failure))
    } finally {
      pending.current = false
      if (current()) setBusy(false)
    }
  }

  return (
    <div className="min-h-0 flex-1 overflow-y-auto p-4">
      <div className="mx-auto grid w-full max-w-xl gap-6 text-xs">
        <form
          className="grid gap-4"
          onSubmit={(event) => {
            event.preventDefault()
            void run("save")
          }}
        >
          <div>
            <h2 className="text-sm font-medium">Collection settings</h2>
            <p className="mt-1 text-muted-foreground">
              Collection name: <span className="font-mono">{schema.name}</span>
            </p>
          </div>
          {!canManage ? (
            <p className="text-muted-foreground">
              Only administrators can change Collection settings.
            </p>
          ) : null}
          <div className="grid gap-1.5">
            <Label htmlFor="collection-settings-title">Title</Label>
            <Input
              id="collection-settings-title"
              value={draft.title}
              disabled={locked}
              onChange={(event) => update({ title: event.target.value })}
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="grid gap-1.5">
              <Label htmlFor="collection-settings-singular">Singular name</Label>
              <Input
                id="collection-settings-singular"
                value={draft.objectNameSingular}
                disabled={locked}
                onChange={(event) => update({ objectNameSingular: event.target.value })}
              />
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="collection-settings-plural">Plural name</Label>
              <Input
                id="collection-settings-plural"
                value={draft.objectNamePlural}
                disabled={locked}
                onChange={(event) => update({ objectNamePlural: event.target.value })}
              />
            </div>
          </div>
          <p className="-mt-2 text-muted-foreground">
            Changing these labels does not rename the Collection or its table.
          </p>
          {schema.type === "post" ? (
            <>
              <p className="text-muted-foreground">
                WordPress post type: <span className="font-mono">{schema.postType}</span>
              </p>
              <div className="flex items-start gap-2">
                <Checkbox
                  id="collection-settings-marker"
                  checked={!!draft.markerSupport}
                  disabled={locked}
                  onCheckedChange={(value) => update({ markerSupport: value === true })}
                />
                <div className="grid gap-1">
                  <Label htmlFor="collection-settings-marker">Marker support</Label>
                  <p className="text-muted-foreground">
                    Set a map location on the WordPress edit screen.
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-2">
                <Checkbox
                  id="collection-settings-region"
                  checked={!!draft.regionSupport}
                  disabled={locked}
                  onCheckedChange={(value) => update({ regionSupport: value === true })}
                />
                <div className="grid gap-1">
                  <Label htmlFor="collection-settings-region">Region support</Label>
                  <p className="text-muted-foreground">
                    Link posts to map regions from the WordPress edit screen.
                  </p>
                </div>
              </div>
            </>
          ) : null}
          {error && !confirmation ? (
            <p role="alert" className="text-destructive">
              {error}
            </p>
          ) : null}
          <div>
            <Button type="submit" size="sm" disabled={!canManage || busy}>
              {busy ? "Saving…" : committed ? "Reload catalog" : "Save changes"}
            </Button>
          </div>
        </form>

        <section className="rounded-md border border-destructive/30 p-4">
          <h2 className="mb-4 text-sm font-medium text-destructive">Danger zone</h2>
          <div className="flex items-center justify-between gap-4">
            <div>
              <p className="font-medium">Clear table</p>
              <p className="mt-1 text-muted-foreground">
                Delete all records and keep the Collection and its fields.
              </p>
              {!canClear ? (
                <p className="mt-1 text-muted-foreground">
                  API sources do not have a local table to clear.
                </p>
              ) : null}
            </div>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="shrink-0 text-destructive hover:text-destructive"
              disabled={locked || !canClear}
              onClick={() => {
                setError(null)
                setConfirmation("clear")
              }}
            >
              Clear table
            </Button>
          </div>
          <div className="mt-4 flex items-center justify-between gap-4 border-t border-destructive/20 pt-4">
            <div>
              <p className="font-medium">Delete table</p>
              <p className="mt-1 text-muted-foreground">
                Delete this Collection, its fields and all records.
              </p>
              {!canDelete ? (
                <p className="mt-1 text-muted-foreground">
                  SVG-bound region Collections cannot be deleted.
                </p>
              ) : null}
            </div>
            <Button
              type="button"
              size="sm"
              variant="destructive"
              className="shrink-0"
              disabled={locked || !canDelete}
              onClick={() => {
                setError(null)
                setConfirmation("delete")
              }}
            >
              Delete table
            </Button>
          </div>
        </section>
      </div>

      <AlertDialog
        open={confirmation !== null}
        onOpenChange={(open) => {
          if (!open && !busy) setConfirmation(null)
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {confirmation === "clear" ? "Clear table?" : "Delete table?"}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {confirmation === "clear"
                ? `Delete every record in “${schemaDisplayTitle(schema)}”? Its fields and settings will remain.`
                : `Delete “${schemaDisplayTitle(schema)}”, its fields and all records? Queries using this Collection must be rebound first.`}
              {schema.type === "post" ? " WordPress posts and their metadata will remain." : null}
              {schema.type === "post" && confirmation === "clear"
                ? " Saving a post again may recreate its MapSVG record."
                : null}
              {schema.type === "api" ? " External API data will remain." : null}
              {" This action cannot be undone."}
            </AlertDialogDescription>
          </AlertDialogHeader>
          {error ? (
            <p role="alert" className="text-xs text-destructive">
              {error}
            </p>
          ) : null}
          <AlertDialogFooter>
            <AlertDialogCancel size="sm" disabled={busy}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              size="sm"
              variant="destructive"
              disabled={busy}
              onClick={(event) => {
                event.preventDefault()
                if (confirmation) void run(confirmation)
              }}
            >
              {busy
                ? "Working…"
                : committed
                  ? "Reload catalog"
                  : confirmation === "clear"
                    ? "Clear table"
                    : "Delete table"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
