import { hasProductFeature } from "@/lib/product-features"
import { ProductFeatureDialog } from "@/components/PremiumFeaturePlaceholder"
import { useEffect, useLayoutEffect, useRef, useState } from "react"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  createCollection,
  fetchWordPressPostTypes,
  type DataSchema,
  type NewCollection,
} from "@/lib/mapsvg-api"

type Props = {
  schemas: DataSchema[]
  onClose: () => void
  onCreated: (schema: DataSchema, current: () => boolean) => Promise<void>
}

export function CreateCollectionDialog({ schemas, onClose, onCreated }: Props) {
  const [postUpsell, setPostUpsell] = useState(false)
  const fullPosts = hasProductFeature("data_source_posts")
  const [draft, setDraft] = useState<NewCollection>({
    type: "object",
    title: "",
    objectNameSingular: "item",
    objectNamePlural: "",
    postType: "",
    markerSupport: true,
    regionSupport: false,
  })
  const [postTypes, setPostTypes] = useState<string[]>([])
  const [typesLoading, setTypesLoading] = useState(false)
  const [typesError, setTypesError] = useState<string | null>(null)
  const [typesRetry, setTypesRetry] = useState(0)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [created, setCreated] = useState<DataSchema | null>(null)
  const life = useRef<object | null>(null)
  const pending = useRef(false)
  useLayoutEffect(() => {
    const owner = {}
    life.current = owner
    return () => {
      if (life.current === owner) life.current = null
    }
  }, [])

  useEffect(() => {
    if (draft.type !== "post" || !fullPosts) return
    const controller = new AbortController()
    let active = true
    setTypesLoading(true)
    setTypesError(null)
    void fetchWordPressPostTypes(controller.signal)
      .then((next) => {
        if (active) setPostTypes(next)
      })
      .catch((failure) => {
        if (active) setTypesError(failure instanceof Error ? failure.message : String(failure))
      })
      .finally(() => {
        if (active) setTypesLoading(false)
      })
    return () => {
      active = false
      controller.abort()
    }
  }, [draft.type, typesRetry])

  const usedPostTypes = new Set(
    schemas.filter((schema) => schema.type === "post").map((schema) => schema.postType),
  )
  const postUnavailable =
    draft.type === "post" &&
    (typesLoading ||
      !!typesError ||
      !postTypes.includes(draft.postType ?? "") ||
      usedPostTypes.has(draft.postType))
  const locked = busy || !!created
  const update = (value: Partial<NewCollection>) => {
    if (!locked) {
      setDraft((current) => ({ ...current, ...value }))
      setError(null)
    }
  }

  const submit = async () => {
    if (draft.type === "post" && !fullPosts) { setPostUpsell(true); return }
    const owner = life.current
    if (!owner || pending.current) return
    if (!created) {
      if (
        !draft.title.trim() ||
        !draft.objectNameSingular.trim() ||
        !draft.objectNamePlural.trim()
      ) {
        setError("Enter a title, singular name and plural name.")
        return
      }
      if (postUnavailable) {
        setError("Choose an available WordPress post type.")
        return
      }
      if (draft.type === "post" && !draft.markerSupport && !draft.regionSupport) {
        setError("Enable Marker support and/or Region support.")
        return
      }
    }
    pending.current = true
    const current = () => life.current === owner
    setBusy(true)
    setError(null)
    try {
      const schema = created ?? (await createCollection({ ...draft }))
      if (!current()) return
      setCreated(schema)
      await onCreated(schema, current)
      if (current()) onClose()
    } catch (failure) {
      if (current()) setError(failure instanceof Error ? failure.message : String(failure))
    } finally {
      pending.current = false
      if (current()) setBusy(false)
    }
  }

  return (
    <>
    <ProductFeatureDialog feature="data_source_posts" open={postUpsell} onOpenChange={setPostUpsell} />
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open && !busy) onClose()
      }}
    >
      <DialogContent className="max-h-[85vh] overflow-y-auto text-xs" showCloseButton={!busy}>
        <DialogHeader>
          <DialogTitle>New Collection</DialogTitle>
          <DialogDescription>
            Create a Collection or connect an existing WordPress post type.
          </DialogDescription>
        </DialogHeader>
        <form
          className="grid gap-4"
          onSubmit={(event) => {
            event.preventDefault()
            void submit()
          }}
        >
          <div className="grid gap-1.5">
            <Label htmlFor="new-collection-type">Type</Label>
            <FormBuilderChoice
              id="new-collection-type"
              value={draft.type}
              disabled={locked}
              onValueChange={(type) => { if (type === "post" && !fullPosts) setPostUpsell(true); else update({ type: type as NewCollection["type"] }) }}
              options={[
                { value: "object", label: "Collection" },
                { value: "post", label: fullPosts ? "WordPress Post Type" : "WordPress Post Type · Premium" },
              ]}
            />
          </div>
          <div className="grid gap-1.5">
            <Label htmlFor="new-collection-title">Title</Label>
            <Input
              id="new-collection-title"
              value={draft.title}
              disabled={locked}
              onChange={(event) => update({ title: event.target.value })}
              placeholder="Sales representatives"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="grid gap-1.5">
              <Label htmlFor="new-collection-singular">Singular name</Label>
              <Input
                id="new-collection-singular"
                value={draft.objectNameSingular}
                disabled={locked}
                onChange={(event) => update({ objectNameSingular: event.target.value })}
                placeholder="sales_rep"
              />
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="new-collection-plural">Plural name</Label>
              <Input
                id="new-collection-plural"
                value={draft.objectNamePlural}
                disabled={locked}
                onChange={(event) => update({ objectNamePlural: event.target.value })}
                placeholder="sales_reps"
              />
            </div>
          </div>
          <p className="-mt-2 text-muted-foreground">
            The Collection name is generated from the plural name and cannot be changed later.
          </p>
          {draft.type === "post" ? (
            <>
              <div className="grid gap-1.5">
                <Label htmlFor="new-collection-post-type">Post type</Label>
                <FormBuilderChoice
                  id="new-collection-post-type"
                  value={draft.postType ?? ""}
                  onValueChange={(postType) => update({ postType })}
                  disabled={locked || typesLoading || !!typesError}
                  placeholder={typesLoading ? "Loading post types…" : "Choose post type"}
                  options={postTypes.map((type) => ({
                    value: type,
                    label: usedPostTypes.has(type) ? `${type} (already connected)` : type,
                    disabled: usedPostTypes.has(type),
                  }))}
                />
                {typesError ? (
                  <div>
                    <p role="alert" className="text-destructive">
                      {typesError}
                    </p>
                    <Button
                      type="button"
                      size="xs"
                      variant="outline"
                      disabled={locked}
                      onClick={() => setTypesRetry((value) => value + 1)}
                    >
                      Retry post types
                    </Button>
                  </div>
                ) : null}
              </div>
              <div className="grid gap-3">
                <div className="flex items-start gap-2">
                  <Checkbox
                    id="new-collection-marker"
                    checked={!!draft.markerSupport}
                    disabled={locked}
                    onCheckedChange={(checked) => update({ markerSupport: checked === true })}
                  />
                  <div className="grid gap-1">
                    <Label htmlFor="new-collection-marker">Marker support</Label>
                    <p className="text-muted-foreground">
                      Set a map location on the WordPress edit screen.
                    </p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <Checkbox
                    id="new-collection-regions"
                    checked={!!draft.regionSupport}
                    disabled={locked}
                    onCheckedChange={(checked) => update({ regionSupport: checked === true })}
                  />
                  <div className="grid gap-1">
                    <Label htmlFor="new-collection-regions">Region support</Label>
                    <p className="text-muted-foreground">
                      Link posts to map regions from the WordPress edit screen.
                    </p>
                  </div>
                </div>
              </div>
            </>
          ) : null}
          {error ? (
            <p role="alert" className="text-destructive">
              {error}
            </p>
          ) : null}
          <DialogFooter>
            <Button type="button" size="sm" variant="outline" disabled={busy} onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" size="sm" disabled={busy || (!created && postUnavailable)}>
              {busy ? "Saving…" : created ? "Reload catalog" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
    </>
  )
}
