import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { BracesIcon, SaveIcon, Trash2Icon } from "lucide-react"
import { QueryBuilder, type RuleGroupType } from "react-querybuilder"
import "react-querybuilder/dist/query-builder.css"
import "@/components/data/saved-data-query-editor.css"
import {
  EMPTY_QUERY_BUILDER,
  PLASMA_QUERY_OPERATORS,
  queryBuilderFieldsForSchema,
} from "@/components/data/savedDataQueries"
import { copyQueryValue, globalQueryDraft, savedQueryContentKey } from "./globalQueryDraft"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { QueryOrderEditor } from "@/components/data/QueryOrderEditor"
import type { BindingOrder } from "../../../../mapsvg/Map/pageBindings"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { SettingsBooleanField } from "@/components/settings-form/SettingsControlField"
import { DatabaseSelect } from "./DatabaseSelect"
import { queryBuilderControls } from "@/components/data/queryBuilderControls"
import {
  type DataSchema,
  type GlobalQueryDraft,
  type GlobalQueryFolder,
  type GlobalSavedQuery,
  schemaDisplayTitle,
  isRegionSchema,
} from "@/lib/mapsvg-api"

type Props = {
  schemas: DataSchema[]
  folders: GlobalQueryFolder[]
  query: GlobalSavedQuery | null
  initialFolderId?: number | null
  onSave: (draft: GlobalQueryDraft) => Promise<void>
  onDelete: (id: string) => Promise<void>
  onCancel: () => void
}

function copyBuilder(builder: RuleGroupType): RuleGroupType {
  return copyQueryValue(builder)
}

export function GlobalQuerySettings({
  schemas,
  folders,
  query,
  initialFolderId,
  onSave,
  onDelete,
  onCancel,
}: Props) {
  const availableSchemas = useMemo(
    () => schemas.filter((schema) => schema.type !== "api" && !schema.remote),
    [schemas],
  )
  const [name, setName] = useState(query?.name ?? "newQuery")
  const [schemaId, setSchemaId] = useState(String(query?.schemaId ?? availableSchemas[0]?.id ?? ""))
  const [folderId, setFolderId] = useState(String(query?.folderId ?? initialFolderId ?? ""))
  const [builder, setBuilder] = useState<RuleGroupType>(() =>
    copyBuilder(query?.builder ?? EMPTY_QUERY_BUILDER),
  )
  const [orderBy, setOrderBy] = useState<BindingOrder | undefined>(undefined)
  const [take, setTake] = useState<number | null | undefined>(undefined)
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const life = useRef<object | null>(null)
  const pending = useRef<object | null>(null)
  const original = useRef<GlobalSavedQuery | null>(query ? copyQueryValue(query) : null)
  const persistedKey = savedQueryContentKey(query)
  const newQueryFolder = query ? null : initialFolderId
  const selectedSchema = availableSchemas.find((schema) => String(schema.id) === schemaId) ?? null
  const canDisablePagination = !!selectedSchema && isRegionSchema(selectedSchema) && !query?.rpc
  const paginationOn = take !== undefined ? take !== null : !canDisablePagination || query?.input.take !== undefined
  const fields = useMemo(
    () => (selectedSchema ? queryBuilderFieldsForSchema(selectedSchema) : []),
    [selectedSchema],
  )

  useLayoutEffect(() => {
    const owner = {}
    life.current = owner
    pending.current = null
    original.current = query ? copyQueryValue(query) : null
    setSaving(false)
    setDeleting(false)
    setDeleteOpen(false)
    setName(query?.name ?? "newQuery")
    setSchemaId(String(query?.schemaId ?? availableSchemas[0]?.id ?? ""))
    setFolderId(String(query?.folderId ?? initialFolderId ?? ""))
    setBuilder(copyBuilder(query?.builder ?? EMPTY_QUERY_BUILDER))
    setOrderBy(undefined)
    setTake(undefined)
    setError(null)
    return () => {
      if (life.current === owner) life.current = null
    }
  }, [persistedKey, newQueryFolder])

  useEffect(() => {
    if (!schemaId && availableSchemas[0]) setSchemaId(String(availableSchemas[0].id))
  }, [schemaId, availableSchemas])

  const draft = () => {
    if (!selectedSchema) throw new Error("Choose an available collection.")
    return globalQueryDraft({
      query: original.current,
      originalSchema: availableSchemas.find(
        (schema) => String(schema.id) === String(original.current?.schemaId),
      ),
      name,
      schema: selectedSchema,
      folderId: folderId ? Number(folderId) : null,
      builder, orderBy, take: take !== undefined ? take : query ? undefined : canDisablePagination ? null : 50,
    })
  }

  const preview = (() => {
    try {
      return JSON.stringify(draft().input, null, 2)
    } catch (failure) {
      return failure instanceof Error ? failure.message : String(failure)
    }
  })()

  const save = async () => {
    const owner = life.current
    if (!owner || pending.current) return
    try {
      // Detach before callbacks: an in-flight request owns exactly this draft.
      const snapshot = draft()
      pending.current = owner
      setSaving(true)
      setError(null)
      await onSave(snapshot)
    } catch (failure) {
      if (life.current === owner) {
        setError(failure instanceof Error ? failure.message : String(failure))
      }
    } finally {
      if (life.current === owner && pending.current === owner) {
        pending.current = null
        setSaving(false)
      }
    }
  }

  const remove = async () => {
    const owner = life.current
    const id = original.current?.id
    if (!owner || !id || pending.current) return
    pending.current = owner
    try {
      setDeleting(true)
      setError(null)
      await onDelete(id)
      if (life.current === owner) setDeleteOpen(false)
    } catch (failure) {
      if (life.current === owner) {
        setError(failure instanceof Error ? failure.message : String(failure))
      }
    } finally {
      if (life.current === owner && pending.current === owner) {
        pending.current = null
        setDeleting(false)
      }
    }
  }

  return (
    <fieldset
      disabled={saving || deleting}
      className="mx-auto flex w-full min-w-0 max-w-6xl flex-col gap-5 overflow-auto p-4"
    >
      <div className="grid gap-2">
        <Label htmlFor="global-query-name">System name</Label>
        <Input
          id="global-query-name"
          value={name}
          maxLength={120}
          readOnly={Boolean(query)}
          onChange={(event) => setName(event.target.value)}
        />
        <p className="text-xs text-muted-foreground">
          {query
            ? "System names are immutable after creation."
            : "Unique camelCase name for this installation."}
        </p>
      </div>
      <div className="grid gap-4 sm:grid-cols-2">
        <div className="grid gap-2">
          <Label htmlFor="global-query-schema">Collection</Label>
          <DatabaseSelect
            id="global-query-schema"
            value={schemaId}
            onValueChange={setSchemaId}
            disabled={saving || deleting}
            options={[
              ...(!selectedSchema && schemaId
                ? [{ value: schemaId, label: `Unavailable collection #${schemaId}` }]
                : []),
              ...availableSchemas.map((schema) => ({
                value: String(schema.id),
                label: schemaDisplayTitle(schema),
              })),
            ]}
          />
        </div>
        <div className="grid gap-2">
          <Label htmlFor="global-query-folder">Folder</Label>
          <DatabaseSelect
            id="global-query-folder"
            value={folderId}
            onValueChange={setFolderId}
            disabled={saving || deleting}
            emptyLabel="Unfiled"
            options={folders.map((folder) => ({ value: String(folder.id), label: folder.title }))}
          />
        </div>
      </div>
      {selectedSchema && fields.length > 0 ? (
        <QueryBuilder
          controlElements={queryBuilderControls}
          disabled={saving || deleting}
          fields={fields}
          operators={PLASMA_QUERY_OPERATORS.map((operator) => ({ ...operator }))}
          query={builder}
          onQueryChange={setBuilder}
          enableMountQueryChange={false}
          parseNumbers="strict"
          listsAsArrays
          resetOnFieldChange
          controlClassnames={{ queryBuilder: "mapsvg-saved-query-builder" }}
        />
      ) : (
        <p className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
          {selectedSchema
            ? "This collection has no supported scalar fields. The query will return all rows."
            : "The linked collection is unavailable. Choose another collection to edit this query."}
        </p>
      )}
      {canDisablePagination && <SettingsBooleanField id="query-pagination" label="Pagination" checked={paginationOn}
        onCheckedChange={enabled => setTake(enabled ? Number(query?.input.take ?? 50) : null)} />}
      {paginationOn && <div className="grid gap-2">
        <Label htmlFor="query-items-per-page">Items per page</Label>
        <Input id="query-items-per-page" type="number" min={1} max={250}
          value={take ?? query?.input.take ?? 50}
          onChange={event => setTake(Number(event.target.value))} />
      </div>}
      <div className="grid gap-2">
        <Label>Default sort order</Label>
        <QueryOrderEditor value={orderBy ?? (query?.input.orderBy ? (Array.isArray(query.input.orderBy) ? query.input.orderBy : [query.input.orderBy]) as BindingOrder : [])}
          fields={fields.map(field => ({ value: field.name, label: String(field.label ?? field.name) }))} onChange={setOrderBy} />
      </div>
      <details className="rounded-md border bg-muted/20">
        <summary className="flex cursor-pointer items-center gap-2 px-3 py-2 text-sm font-medium">
          <BracesIcon className="size-4" />
          Prisma input
        </summary>
        <pre className="max-h-72 overflow-auto border-t p-3 text-xs leading-relaxed">{preview}</pre>
      </details>
      {error ? (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      ) : null}
      <div className="flex items-center justify-between border-t pt-4">
        <div>
          {query ? (
            <Button
              type="button"
              variant="destructive"
              size="sm"
              onClick={() => setDeleteOpen(true)}
            >
              <Trash2Icon />
              Delete
            </Button>
          ) : null}
        </div>
        <div className="flex gap-2">
          <Button type="button" variant="outline" size="sm" onClick={onCancel}>
            Cancel
          </Button>
          <Button
            type="button"
            size="sm"
            disabled={saving || deleting || !selectedSchema}
            onClick={() => void save()}
          >
            <SaveIcon />
            Save query
          </Button>
        </div>
      </div>
      <Dialog
        open={deleteOpen}
        onOpenChange={(open) => {
          if (!deleting) setDeleteOpen(open)
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Delete query</DialogTitle>
            <DialogDescription>
              Delete “{query?.name}”? Queries used by maps must be rebound first.
            </DialogDescription>
          </DialogHeader>
          {error ? (
            <p role="alert" className="text-sm text-destructive">
              {error}
            </p>
          ) : null}
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              disabled={saving || deleting}
              onClick={() => setDeleteOpen(false)}
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="destructive"
              disabled={saving || deleting}
              onClick={() => void remove()}
            >
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </fieldset>
  )
}
