import type { DataSchema } from "@/lib/mapsvg-api"

const flag = (value: unknown) => value === true || value === 1 ||
  (typeof value === "string" && ["1", "true", "on", "yes"].includes(value.trim().toLowerCase()))

/** A duplicate is a new, detached create draft, never an update to its source. */
export function duplicateCollectionRecord(schema: DataSchema, row: Record<string, unknown>): Record<string, unknown> {
  return structuredClone(Object.fromEntries((schema.fields ?? []).filter(field =>
    field.name !== "id" && field.type?.toLowerCase() !== "id" && !flag(field.readonly) &&
    Object.prototype.hasOwnProperty.call(row, field.name),
  ).map(field => [field.name, row[field.name]])))
}
