import { DatabaseNavigationProvider } from "./DatabaseNavigation"
import { DatabaseWorkspace } from "./DatabaseWorkspace"
import type { ComponentProps } from "react"

export function DeferredDatabaseWorkspace({ initialQueryId, ...props }: ComponentProps<typeof DatabaseWorkspace> & {
  initialQueryId: ComponentProps<typeof DatabaseNavigationProvider>["initialQueryId"]
}) {
  return <DatabaseNavigationProvider initialQueryId={initialQueryId}><DatabaseWorkspace {...props} /></DatabaseNavigationProvider>
}
