import {
  fetchCollectionRows,
  isRegionSchema,
  schemaDisplayTitle,
  type DataSchema,
} from "@/lib/mapsvg-api"
import { queryContentKey } from "@/components/database/globalQueryDraft"
import type { RegionAdapter } from "./adapters"

export function regionCatalogKey(schemas: DataSchema[]): string {
  return queryContentKey(schemas.filter(isRegionSchema))
}

/** Global Database has no active Map. Region source is an explicit Collection choice. */
export function createCollectionRegionAdapter(schemas: DataSchema[], preferences: Pick<RegionAdapter, "tableName" | "rememberSource" | "preferenceKey" | "preferenceError"> = { tableName: "" }): RegionAdapter | undefined {
  const regions = schemas.filter(isRegionSchema)
  if (!regions.length) return undefined
  const byName = new Map(regions.map((schema) => [schema.name, schema]))
  return {
    ...preferences,
    sources: regions.map((schema) => ({
      tableName: schema.name,
      title: schemaDisplayTitle(schema),
    })),
    async listRegions(tableName) {
      const schema = tableName ? byName.get(tableName) : undefined
      if (!schema) throw new Error("Choose an available region collection.")
      // The established region selector requires the full source, like Map.getRegionsList().
      const rows = await fetchCollectionRows(schema, { perpage: 0 })
      return rows.map((row) => {
        if (row.id == null)
          throw new Error("The region collection returned a record without an id.")
        return { id: String(row.id), title: row.title == null ? String(row.id) : String(row.title) }
      })
    },
  }
}
